(window.RAGHIB_FULL = window.RAGHIB_FULL || {})["2-5"] = [{"a": [87], "v": 1, "p": 255, "ev": 1, "ep": 256, "sid": 256, "t": "قوله- عز وجل:\n﴿وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَقَفَّيۡنَا مِنۢ بَعۡدِهِۦ بِٱلرُّسُلِۖ وَءَاتَيۡنَا عِيسَى ٱبۡنَ مَرۡيَمَ ٱلۡبَيِّنَٰتِ وَأَيَّدۡنَٰهُ بِرُوحِ ٱلۡقُدُسِۗ أَفَكُلَّمَا جَآءَكُمۡ رَسُولُۢ بِمَا لَا تَهۡوَىٰٓ أَنفُسُكُمُ ٱسۡتَكۡبَرۡتُمۡ فَفَرِيقٗا كَذَّبۡتُمۡ وَفَرِيقٗا تَقۡتُلُونَ﴾⟪2:87⟫\nالآية: (87) سورة البقرة.\nالاقتفاء إتباع القفا، كما أن الارتداف إتباع الردف، وقفوته: أصبت قفاه نحو: قادته وبطنته إذا رميت ذلك منه، ثم يكني به عن الاغتياب، وقافية الشعر لاعتبار الاقتفاء فيها، والقفاوة ما يتفقد به الغير على سبيل الإيثار، والهوى اسم للقوة الشهوية، وأصله من الهوى، لأنه يهوى بصاحبه فلا يستقر به، والروح من الحيوان اسم للجزء الذي معه تحصل الحياة، ولما كانت الحياة تختلف، فمنها ما تشترك فيه الحيوانات ويحصل به التحرك والسعي واستجلاب النافع واستدفاع المضار، ومنها الحياة التي يختص بها الإنسان، وبها يكون الفكر والروية ولأجله قيل، فلان ليس بحي أو هو ميت إذا ضعف ذلك فيه، ومنها الحياة التي يستفيدها الإنسان بالعلم وهو أس ما يتوصل به إلى الحياة الأبدية، وإياها قصد بقوله: ﴿أَوَمَن كَانَ مَيۡتٗا فَأَحۡيَيۡنَٰهُ﴾⟪6:122⟫ صار الروح يقال لكل ذلك، فيقال \" ذوروح \" لكل حيوان، وقيل للقرآن روح لما كان سببا للحياة الأبدية قال تعالى: ﴿وَكَذَٰلِكَ أَوۡحَيۡنَآ إِلَيۡكَ رُوحٗا مِّنۡ أَمۡرِنَاۚ﴾⟪42:52⟫، وقيل: سمي عيسى عليه السلام روحا، لأنه كان يحيى الموتى فصار كالروح، وقيل: سمي بذلك لأنه كان يفيد الناس ويعلمهم ما يتوصلون به إلى الحياة الأبدية، وقيل: سمي بذلك لقوله: ﴿فَنَفَخۡنَا فِيهِ مِن رُّوحِنَا﴾، وذلك أنه لم يخلق من ماء ذكر وأنثى، وإنما قال له: (كن) وسمي جبرائيل (عليه السلام) روح القدس، والروح الأمين، وهذه الآية توكيد لذمهم والإنباء عن بعدهم عن الإيمان وأنهم قد أتاهم موسى بالكتاب، ثم اتخذوا العجل وأتاهم رسل فلم يعرجوا عليهم، وجاءهم\n⟦1:256⟧\nعيسى - عليه السلام بالمعجزات الباهرة فكذبوه، وقوله: ﴿فَفَرِيقٗا كَذَّبۡتُمۡ وَفَرِيقٗا تَقۡتُلُونَ﴾⟪2:87⟫ يصح أن يكون معطوفا على قوله ﴿وَأَيَّدۡنَٰهُ بِرُوحِ ٱلۡقُدُسِۗ﴾⟪2:87⟫ ويكون قوله ﴿أَفَكُلَّمَا جَآءَكُمۡ رَسُولُۢ﴾⟪2:87⟫ فصلا بينهما على سبيل الإمكان عليهم، ويصح أن يكون معطوفا على قوله:] \" استكبرتم \"، وقوله: ﴿أَفَكُلَّمَا﴾⟪2:87⟫ استئناف وبين باتباعهم الهوى غاية معانيهم، فإن متبعه مخطئ وإن أصاب، فالإصابة منه على غيره اعتماد، إذ هو كالبهيمة المتناولة لما تدعو إليه شهوتها صوابا كان أم خطأ، ثم زاد في ذمهم بوصفهم بالاستكبار إذ هو مقر النقائص، فإنه نتيجة الإعجاب، والإعجاب نتيجة الجهل بالنفس والجهل بالنفس مقارن للجهل بخالقها، ولذلك قال تعالى: ﴿وَلَا تَكُونُواْ كَٱلَّذِينَ نَسُواْ ٱللَّهَ فَأَنسَىٰهُمۡ أَنفُسَهُمۡۚ﴾⟪59:19⟫\nإن قيل: لم قال: ﴿فَفَرِيقٗا كَذَّبۡتُمۡ وَفَرِيقٗا تَقۡتُلُونَ﴾⟪2:87⟫ وهلا جعلا ماضيين أو مستقبلين؟ قيل: أما من حيث اللفظ، فلأنه لما لم يكن يفسد المعنى روعي فيه المجانسة بين الفواصل ليكون اللفظ أحسن، وأما من حيث المعنى: فللتنبيه أنهم لم يتوقفوا في تكذيب من جاءهم من الأنبياء، فذكره بلفظ الماضي، إذ لا مزاولة فيه، وذكر القتل بلفظ الاستقبال تنبيها أنهم يزاولون قتله قدروا عليه أم لم يقدروا."}, {"a": [88], "v": 1, "p": 256, "ev": 1, "ep": 257, "sid": 257, "t": "قوله - عز وجل:\n﴿وَقَالُواْ قُلُوبُنَا غُلۡفُۢۚ بَل لَّعَنَهُمُ ٱللَّهُ بِكُفۡرِهِمۡ فَقَلِيلٗا مَّا يُؤۡمِنُونَ﴾⟪2:88⟫ الآية (88) سورة البقرة.\nأصل الغلف ستر الشيء بالشيء الذي يجعل فيه، ومنه غلفت السيف والسرج والرحل واللحية بالغالبة، والأغلف الأقلف لكون ذلك منه في غلاف من غلفته أي قلفته وعزلته، فقوله: (غلف): قيل هو جمع غلاف وأصله غلف، فخفف، وقرئ غرف ككتب وقيل: هو جمع أغلف، فعلى الأول قيل معناه: قلوبنا أوعية للعلم لا تسمع علما إلا وعته إلا ما تقول، بمعنى أن ما يقوله ليس بعلم، وعلى الثاني\n⟦1:257⟧\nمعناه: قلوبنا مغطاة عما تدعونا إليه فلا نفهمه كما قال: ﴿وَقَالُواْ قُلُوبُنَا فِيٓ أَكِنَّةٖ مِّمَّا تَدۡعُونَآ إِلَيۡهِ﴾⟪41:5⟫ الآية ..\nورد الله تعالى ذلك عليهم بأن ذلك لكونهم مبعدين عن العلم لسوء فعلهم، وقد تقدم أن سبب المانع من الفضيلة سببان: أحدهما: ابتداؤه ليس من جهة الإنسان نفسه، وهو متجاف عنه كمرتكب قبيح لزوال عقله بجنون أو مرض، والثاني: ابتداؤه من جهته، وهو مأخوذ به كمرتكب ذنب لسكره، فبين الله تعالى أن قلوبهم ممنوعة عن العلم بكفرهم وذلك من جهتهم، وقوله: ﴿فَقَلِيلٗا مَّا يُؤۡمِنُونَ﴾⟪2:88⟫ أي لم يؤمنوا إلا إيمانا قليلا أو زمانا قليلا، وذلك غير معتد به، لأن الإيمان هو التصديق المخصوص، ومتى لم يحصل كمالا لم يعتد به، ولذلك عظم عقوبة ذلك بقوله: ﴿أَفَتُؤۡمِنُونَ بِبَعۡضِ ٱلۡكِتَٰبِ وَتَكۡفُرُونَ بِبَعۡضٖۚ﴾⟪2:85⟫، ونحو هذه الآية قوله: ﴿بَلۡ طَبَعَ ٱللَّهُ عَلَيۡهَا بِكُفۡرِهِمۡ فَلَا يُؤۡمِنُونَ إِلَّا قَلِيلٗا﴾⟪4:155⟫"}, {"a": [89], "v": 1, "p": 257, "ev": 1, "ep": 258, "sid": 258, "t": "قوله - عز وجل:\n﴿وَلَمَّا جَآءَهُمۡ كِتَٰبٞ مِّنۡ عِندِ ٱللَّهِ مُصَدِّقٞ لِّمَا مَعَهُمۡ وَكَانُواْ مِن قَبۡلُ يَسۡتَفۡتِحُونَ عَلَى ٱلَّذِينَ كَفَرُواْ فَلَمَّا جَآءَهُم مَّا عَرَفُواْ كَفَرُواْ بِهِۦۚ فَلَعۡنَةُ ٱللَّهِ عَلَى ٱلۡكَٰفِرِينَ﴾⟪2:89⟫ الآية: (89) سورة البقرة.\nالاستفتاح: طلب الفتح، والفتح ضربان، فتح إلاهي، وهو النصرة بالوصول إلى العلوم والهدايات التي هي ذريعة إلى الثواب والمقامات المحمودة، وفتح دنيوي، وهو النصرة في الوصول إلى اللذات البدنية وعلى الأول قوله: ﴿إِنَّا فَتَحۡنَا لَكَ فَتۡحٗا مُّبِينٗا﴾⟪48:1⟫، وقوله ﴿فَعَسَى ٱللَّهُ أَن يَأۡتِيَ بِٱلۡفَتۡحِ أَوۡ أَمۡرٖ﴾⟪5:52⟫ وعلى الثاني قوله:\n﴿فَلَمَّا نَسُواْ مَا ذُكِّرُواْ بِهِۦ فَتَحۡنَا عَلَيۡهِمۡ أَبۡوَٰبَ كُلِّ شَيۡءٍ﴾⟪6:44⟫، وقوله: ﴿يَسۡتَفۡتِحُونَ﴾⟪2:89⟫ قيل معناه:\n⟦1:258⟧\nيستعملون خبره من الناس مرة، وقيل يطلبون من الله في بذكره الظفر، وقيل: كانوا يقولون: إنا ننصر لمحمد عليه السلام على عبدة الأوثان، وكل ذلك داخل في عموم الاستفتاء، فبين الله تعالي من جهلهم أنهم كانوا ينتظرونه، وكانوا يعرفون وصفه كما قال تعالى: ﴿يَعۡرِفُونَهُۥ كَمَا يَعۡرِفُونَ أَبۡنَآءَهُمۡۖ﴾، وكما قال: ﴿ٱلنَّبِيَّ ٱلۡأُمِّيَّ ٱلَّذِي يَجِدُونَهُۥ مَكۡتُوبًا عِندَهُمۡ فِي ٱلتَّوۡرَىٰةِ وَٱلۡإِنجِيلِ﴾⟪7:157⟫، فلما جاءهم كتاب لا منافاة بينه وبين التوراة في الأصول، وعرفوا عيانا ما كانوا عرفوه من قبل إخبارا كفروا به، ثم قال: ﴿فَلَعۡنَةُ ٱللَّهِ عَلَى ٱلۡكَٰفِرِينَ﴾⟪2:89⟫ تنبيها أن اللعن ثابت للكفار، وهم كفار، فاللعن عليهم، وأما معنى اللعن هو إفضاء على وجه الإهانة، ومن قال: هو العذاب، فمن حيث أنه لا تنفك لعنة الله عن العذاب، وأما تكرير لما، فقد قيل جواب الأول محذوف، وقوله: ﴿كَفَرُواْ بِهِۦۚ﴾⟪2:89⟫ إنما هو جواب للثاني، وقيل: لما بين فصله لما وجوابه بقوله: ﴿وَكَانُواْ مِن قَبۡلُ يَسۡتَفۡتِحُونَ﴾⟪2:89⟫ أعتاد ذكره بلفظ يقتضي زيادة فائدة، ثم أجاب، وقيل جواب الأول \" الفاء \"، و (كفروا به) جواب الثاني نحو قولك: لا جاء زيد فلما قعد أوسعت له ..."}, {"a": [90], "v": 1, "p": 258, "ev": 1, "ep": 259, "sid": 259, "t": "قوله - عز وجل -:\n﴿بِئۡسَمَا ٱشۡتَرَوۡاْ بِهِۦٓ أَنفُسَهُمۡ أَن يَكۡفُرُواْ بِمَآ أَنزَلَ ٱللَّهُ بَغۡيًا أَن يُنَزِّلَ ٱللَّهُ مِن فَضۡلِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦۖ فَبَآءُو بِغَضَبٍ عَلَىٰ غَضَبٖۚ وَلِلۡكَٰفِرِينَ عَذَابٞ مُّهِينٞ﴾⟪2:90⟫.\nالآية: (90) من سورة البقرة.\nبئس؟ كلمة تستكمل في جميع المذام، كما أن \" نعم \" تستعمل في جميع المادح، وأصله من البؤس، وهو المكروم وتصور منه الفقر تارة، فقيل بئيس، والنكاية في الغيرة فقيل بؤس، وسمى البسالة بأسا به وأصل البغي الطلب، واختلفت مكانيه لأختلاف المسند إليه، وربما خولف بين\n⟦1:259⟧\nمصادرها، فمتى أسند إلى الرأي فلابتغائها لمن يحرم عليها، وإذا أسند إلى المتكبر فلطلبه إكراما لا يستحقه، وإذا أسند إلى الرأي فلطلبه متطلعا، والهوان يتصور على وجهين أحدهما: التذلل للإنسان في نفسه لما لا يلحق به غضاضة، فيمدح به نحو المؤمن هين لين، والثاني: أن يكون مرجعه خلط ستليه على طريق الاستخفاف فيذم به، وعلى الوجهين استعمل \" ذلك فبين الله تعالى أنه بئس\nشيئا باعوا أنفسهم به كفرهم بكتب الله المنزلة، ثم بين أن أعظم هذا الجنس أن يفعل دلك حسدا على من خصه الله تعالى بفضل من عنده، وفضله ههنا أجل الفضائل، وهو النبوة، ثم بين أنهم بذلك استحقوا بذلك أنواعا من الغضب نوعا بعد نوع نحو قوله: ﴿يُضَٰعَفۡ لَهُ ٱلۡعَذَابُ﴾ ..\nنعوذ بالله منه."}, {"a": [91], "v": 1, "p": 259, "ev": 1, "ep": 261, "sid": 260, "t": "قوله- عز وجل:\n﴿وَإِذَا قِيلَ لَهُمۡ ءَامِنُواْ بِمَآ أَنزَلَ ٱللَّهُ قَالُواْ نُؤۡمِنُ بِمَآ أُنزِلَ عَلَيۡنَا وَيَكۡفُرُونَ بِمَا وَرَآءَهُۥ وَهُوَ ٱلۡحَقُّ مُصَدِّقٗا لِّمَا مَعَهُمۡۗ قُلۡ فَلِمَ تَقۡتُلُونَ أَنۢبِيَآءَ ٱللَّهِ مِن قَبۡلُ إِن كُنتُم مُّؤۡمِنِينَ﴾⟪2:91⟫ الآية (91) سورة البقرة.\nوراء يقال للخلف والقدام، وهو في الأصل مصدر وارى، فلما كان المصدر يضاف إلى الفاعل وإلى المفعول، فمتى قيل وراء زيد بمعنى قدامه، فمعناه الذي يواري زيد، وإذا قيل بمعنى \" خلف \"، فهو الذي يواريه زيد، ثم جعل ظرفا مثل كثير من المصادر، وإن قيل: كيف قيل للخلف \" فلم تقلتون \"، وكان القتل من السلف لا منهم، قيل: لما كان من عادة العرب أن ينسبوا إلى أنفسهم على طريق الفخر مأثرا بأيهم، فيقول فعلنا كذا متصورين بصورتهم خوطبوا أيضا في نسبة مثالبهم إليهم على ذلك\n⟦1:260⟧\nالوجه، وقال ابن عباس [رضي الله تعالى] عنهما : (إذا عمل معصية، فمن أنكرها فقد برئ منها، ومن رضيها كان كمن فعلها)، فلما رضوا فدل آبائهم فكأنهم هم فعلوه، فلذلك خاطبهم بذلك،\nإن قيل: كيف قال: (تقتلون من قبل) ولا يجور في الكلام تخرج أمس، قيل: في ذلك وجهان.\nأحدهما: أن عادة العرب إذا أرادوا أن يخبروا عن تعاطي فعلى مداوم عليه قرنوا لفظ الماضي بالمستقبل تنبيها على المداومة عليه نحو قول الشاعر:\nولقد أمر على اللئيم يسبني ...\nفمضيت ثمة قلت لا يعنيني\nوعلى ذلك يقال: فعلت كذا قبل وبعد، وافعل كذا قبل وبعد، فيجئ تارة بلفظ الماضي وتارة بلفظ المستقبل، والثاني إن قوله ﴿مِن قَبۡلُ﴾⟪2:91⟫ يتعلق بمقتضى قوله \" فلم \" الذي هو بحث عن علة الشيء، فكأنه قليل: أخبرني قبل عن سبب قتلكم، ومعنى لم تقتلون لم ترومون قتلهم، وهذا أوضح، وقوله: ﴿وَيَكۡفُرُونَ بِمَا وَرَآءَهُۥ﴾⟪2:91⟫ قيل معناه بما أنزل الله بعده من الإنجيل والقرآن، وقيل: معناه بما تنطوي عليه التوراة، وذاك أن انتساب المعنى إلى اللفظ انتساب المتأخر إلى المتقدم والباطن إلى الظاهر، ولهذا يقال: وراء هذا الكلام معنى لطيف، وفي ضمنه شيء حسن، وقد بين الله تعالي أنهم يدعون\n⟦1:261⟧\nالإيمان بالتوراة وهم كاذبون في دعواهم، فإنهم لا يكونون مؤمنين بها إذا كفروا بما يتضمنه من أخبار النبي عليه السلام وكفروا بما يتلوه من كتاب الله - عز وجل- فإن النبوة والكتاب لا يختلف من حيث ما هو نبوة وكتاب، ومن لم يؤمن ببعضه، فهو في حكم من لم يؤمن بشيء منه، ولهذا قال: ﴿أَفَتُؤۡمِنُونَ بِبَعۡضِ ٱلۡكِتَٰبِ وَتَكۡفُرُونَ بِبَعۡضٖۚ﴾⟪2:85⟫، فأثبت لهم أشد العذاب الذي يستحقه الكافر المطلق، ثم بين أنه هو الحق أي ذلك المعنى الذي هو القرآن حتى لا يزاحمه في ذاته ضد وهو مصدق لما تقدمه لا منافاة بينهما في ألاصول، ثم بين [تعالى] ثانيا إبطال ما ادعوه بقتلهم الأنبياء إن كانت التوراة لم تقتض ذلك، ثم قال: ﴿إِن كُنتُم مُّؤۡمِنِينَ﴾⟪2:91⟫ تنبيها أنكم لستم بمؤمنين، إذ المؤمن لا يقتل الأنبياء، وفي كل ذلك حجة على بطلان ما ادعوه من الإيمان بالتوراة."}, {"a": [92], "v": 1, "p": 261, "ev": 1, "ep": 262, "sid": 262, "t": "قوله- عز وجل:\n﴿وَلَقَدۡ جَآءَكُم مُّوسَىٰ بِٱلۡبَيِّنَٰتِ ثُمَّ ٱتَّخَذۡتُمُ ٱلۡعِجۡلَ مِنۢ بَعۡدِهِۦ وَأَنتُمۡ ظَٰلِمُونَ﴾⟪2:92⟫\nالآية (92) سورة البقرة.\nجعل ذلك أيضا دلالة على دلالة قولهم: ﴿نُؤۡمِنُ بِمَآ أُنزِلَ عَلَيۡنَا﴾⟪2:91⟫ فكأنه قيل: كيف آمنتم به وقد أتاكم موسى بالآيات البينات فما لبثتم أن عبدتم العجل ظلما، وظلمهم الإخلال بآيات الله وبيناته وتلقيها بالكفران والكفر، وفي تخصيص ثم زيادة فائدة، وهي أن ذلك منكم بعد تدبر الآيات والتمكن من معرفتها، والآيات.\nههنا هي الآيات التسع المذكورة في قوله: ﴿وَلَقَدۡ ءَاتَيۡنَا مُوسَىٰ تِسۡعَ ءَايَٰتِۭ بَيِّنَٰتٖۖ﴾⟪17:101⟫، وقوله: ﴿وَأَدۡخِلۡ يَدَكَ فِي جَيۡبِكَ تَخۡرُجۡ بَيۡضَآءَ مِنۡ غَيۡرِ سُوٓءٖۖ فِي تِسۡعِ ءَايَٰتٍ إِلَىٰ فِرۡعَوۡنَ وَقَوۡمِهِۦٓۚ﴾⟪27:12⟫\n⟦1:262⟧"}, {"a": [93], "v": 1, "p": 262, "ev": 1, "ep": 264, "sid": 263, "t": "قوله - عز وجل -:\n﴿وَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ خُذُواْ مَآ ءَاتَيۡنَٰكُم بِقُوَّةٖ وَٱسۡمَعُواْۖ قَالُواْ سَمِعۡنَا وَعَصَيۡنَا وَأُشۡرِبُواْ فِي قُلُوبِهِمُ ٱلۡعِجۡلَ بِكُفۡرِهِمۡۚ قُلۡ بِئۡسَمَا يَأۡمُرُكُم بِهِۦٓ إِيمَٰنُكُمۡ إِن كُنتُم مُّؤۡمِنِينَ﴾⟪2:93⟫\nالآية: (93) سورة البقرة.\nقوله: (اسمعوا)، قيل معناه: افهموا، وقيل معناه: اعملوا به، ووجه ذلك أن الشيء يسمع به، ثم يتخيل، ثم يفهم، ثم يعقد، ثم يعمل به إن كان ذلك المسموع مما يقتضي عملا، ولا كان السماع مبدأ والعمل غاية وما بينهما وسائط صح أن يذكر، ويراد به بعض الوسائط وأن يعني به الغاية وهي العمل، فمن قال معنى (واسمعوا) أي اعملوا به، فنظر منه إلى الغاية، ومن قال: افهموا واعقلوا فنظر منه إلى البدء أو إلى الوسائط، وقال بعضهم: قد قالوا قولا سمعنا وعصينا، وقيل: إنما سمعوه وتلقوه بالعصيان، فكأنهم قالوا بدلك قولا، كقول الشاعر:\nامتلأ الحوض وقال قطنى\nوقال الآخر: قال جناحاه لرجليه الحقا\n﴿وَأُشۡرِبُواْ فِي قُلُوبِهِمُ ٱلۡعِجۡلَ﴾⟪2:93⟫ ...\nمن عادة العرب أنهم إذا أرادوا العبارة عن مخامرة حب أو بغض في القلب أن يستعيروا لها اسم الشراب، إذ هو أبلغ منجاع في البدن، ولذلك قالت الأطباء:\n⟦1:263⟧\nالماء مطية الأغذية، والأدوية، لركوبها يبلغ أقاصي الأمكنة، وعلى هذه الراعية قال الشاعر:\nتغلغل حيث لم يبلغ شراب\n....\nولا حزن ولم يبلغ سرور\nوقال أهل النحو: أريد حب العجل، فحذف المضاف تحقيقا ، ويجب أن يعلم أنه لو قيل حب العجل، لم يكن له من المبالغة ماله بحذفه، لأن فيه تنبيها أن لفرط شغفهم به ثبت صورة العجل في قلوبهم راسخة، وإن زالت ذاته الجسمية، ثم بين أن ذلك [كذلك] بسب كفرهم، لا أنه تعالى ظلمهم به، وما قال السدي وابن جرير أن موسى- عليه السلام- لما رجع إلى [قومه] برد العجل الذي عبدوه، فذراه في اليم، فلم يشربه أحد أحبه إلا خرج على شاربيه الذهب، وليس ينافي ما تقدم تصورت ذلك حقيقة أم تصورته كناية وإشارة، وقال بعضهم: معنى أشربوا من قولهم: \" أشربت البعير \" إذا شددت حبلا في عنقه، قال:\nوأشربتها الأقران حتى وقصتا ...\nبقرح وقد ألقين كل جنين\nفكأنما شد في قلوبهم العجل لفرط شغفهم به، فهو راجع إلى الأول تحقيقه وإن خالفه تشبيها وتمثيلا، ثم بكتهم تعالى بقياس شرطي يدل على إبطال دعواهم الإيمان بالتوراة وهو قوله:\n﴿بِئۡسَمَا يَأۡمُرُكُم بِهِۦٓ إِيمَٰنُكُمۡ إِن كُنتُم مُّؤۡمِنِينَ﴾⟪2:93⟫، وتقديره: إن كنتم مؤمنين، فإيمانكم أمركم بذلك، وكل إيمان أمر بذلك فإيمان مذموم، وقد ثبت أن الإيمان بالتوراة ليس بمذموم ولا يظهر بالمذموم، فإذا\n⟦1:264⟧\nلستم بمؤمنين، فكيف تدعون الإيمان بما أنزل إليكم، وقال الزجاج في قوله: ﴿إِن كُنتُم مُّؤۡمِنِينَ﴾⟪2:93⟫. [ما كنتم مؤمنين].\nفإن عنى أن إن ههنا لفظة للنفي فدلك بعيد، وإن عنى أنه شرط مقتضاه النفي كما تقدم فصحيح والكلام في أنه كيف جعل الإيمان أمرا في قوله: ﴿يَأۡمُرُكُم بِهِۦٓ إِيمَٰنُكُمۡ﴾⟪2:93⟫ فقد تقدم في صدر الكتاب فصل كلي يكفي الاشتغال بهذه التفاصيل."}, {"a": [94], "v": 1, "p": 264, "ev": 1, "ep": 266, "sid": 265, "t": "قوله - عز وجل -:\n﴿قُلۡ إِن كَانَتۡ لَكُمُ ٱلدَّارُ ٱلۡأٓخِرَةُ عِندَ ٱللَّهِ خَالِصَةٗ مِّن دُونِ ٱلنَّاسِ فَتَمَنَّوُاْ ٱلۡمَوۡتَ إِن كُنتُمۡ صَٰدِقِينَ﴾⟪2:94⟫\nالآية (94) سورة البقرة.\nالخالص كالصافي، لكن الصافي يقال فيما لم يكن قبل فيه شوب، ولا يقال: خالص إلا ما كان فيه شوب من [قبل]، فزال عنه، ولذلك قال الشاعر:\nخلاص الخمر من نسج الفدام\nفاعتبر فيه معنى التخلص والتمني تقدير تأتي مشيته والتحدث به إما ضميرا، وإما مقالا، ودون لما كان في الأصل القاصر عن الشر اعتبر ذلك في المكان تارة وفي الشرف تارة، وفي الاختصاص تارة، فإذا قيل: هذا لي دونك، فهو مفيد للاختصاص، ومعناه: أنت تقصر عنه، وإن قيل كيف قال: ﴿مِّن دُونِ ٱلنَّاسِ﴾⟪2:94⟫ والمخاطبون أيضا من الناس؟\nقيل: قد قال بعضهم لفظه عام، ومعناه خاص، أي دون سائر الناس، وقال بعضهم في ذلك لطيفة، وهو أنه يقال: \" فلأن ليس من الناس، وذلك متردد بين المدح والذم، فالمدح نحو قول بعضهم: فلان ليس إنسانا، بل هو ملك كريم ...\n⟦1:265⟧\nوقال الشاعر\nفلست بإنسي ولكن لملاك\nوالذم نحو: فإن جلهم أو كلهم بقر\nولما كانت الدار الآخرة لا تحصل للناس خالصة، بل لأبد في نيلها من تحمل شوائب وتجرع نوائب، وكانوا قد ادعوا أنها لهم خالصة قيل لهم ذلك بمعنى إن كنتم جنسا غير الناس في أن تحصل لكم الدار الآخرة خالصة [على حسب ما تحصل للناس] فتمنوا الموت، وإنما قيل لهم \" تمنوا الموت \"، لأنهم قالوا: ﴿لَن يَدۡخُلَ ٱلۡجَنَّةَ إِلَّا مَن كَانَ هُودًا﴾⟪2:111⟫، وقالوا:\n﴿نَحۡنُ أَبۡنَٰٓؤُاْ ٱللَّهِ وَأَحِبَّٰٓؤُهُۥۚ﴾⟪5:18⟫، فبين الله تعالي كذبهم في دعواهم ذلك فقال: إن كنتم أحباء الله، فالمحبة داعية إلى الشوق، والشوق داع إلى محبة لقاء المحبوب، ومحبة لقائه داعية إلي تمنى سهول السبيل إليه، ولا سبيل إلى الطريق إليه إلا بالموت، فيجب أن يكون الموت متمنى، فترككم تمني ذلك دلالة أن لا [محبة منكم له] ..\nإن قيل: فهل يجوز للمسلم أن يتمنى الموت؟ قيل:\nأنا تمنيه على أن سخط ما أراد الله من حياته فلا يجوز فإن ذلك مضادة الله في أرادته، وتسخط لقضائه، وإما على أن يكرهه إذا أتاه، فجائز، وهو غاية الحكمة وشعار المؤمن المحق، ولذلك قيل: \" لا يكون الحكيم حكيما حتى يعلم أن الموت يعتقه والحياة تسترقه، وقيل: \" سرور المؤمن بموته\n⟦1:266⟧\nسرور القادم على أهله \"، وقال عليه السلام: \" من أحب لقاء الله أحب الله لقاء، ومن كره لقاء الله كره\nالله لقاءه \".\nوقال علي- رضي الله عنه:\n\" لا أبالي سقطت على الموت أو سقط الموت علي \" إنما قيل: كيف أعاد الشرط، فقال: إن كنتم صادقين \"، وذلك يقتضي جوابا أخر، قيل: إن ذلك كالبدل من الشرط الأول، فإن مقتضاهما واحد، لكن الصدق يتناول اللفظ، وقوله: ﴿إِن كَانَتۡ لَكُمُ ٱلدَّارُ ٱلۡأٓخِرَةُ﴾⟪2:94⟫ يتناول ذات الشيء، فصار كقول القائل لمن يدعي فعلا: \" إن فعلته فلك كدا إن صدقت \" ..."}, {"a": [95], "v": 1, "p": 266, "ev": 1, "ep": 267, "sid": 267, "t": "قوله - عز وجل -:\n﴿وَلَن يَتَمَنَّوۡهُ أَبَدَۢا بِمَا قَدَّمَتۡ أَيۡدِيهِمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ﴾⟪2:95⟫ الآية: (95) - سورة البقرة.\nالتقدم إما أن يقال باعتبار زمانين، فيقال حديث وقديم، وإما باعتبار تقدم على الزمان، فيقال: قديم أي متقدم وجوده على وجود الزمان وإما بالشرف فيقال: \" فلان متقدم على فلأن \" أي أشرف منه منزلة وإما لما لا يصح وجوده إلا بوجود الأخر، فيقال لذلك الآخر قديم كقولك: الواحد متقدم على العدد، بمعنى أنه لو توهم ارتفاعه لارتفع الأعداد، وكما استعملوا القديم والحديث باعتبار زمانين استعملوا التقدم والتأخير، وقدام وخلف باعتبار مكانين، وباعتبار التقدم المكاني سمي القدم قدما، وقد بت الله تعالى القول بأن لا تمنى للموت منهم قط، لما احتقبوه من الآثام، وفي ذلك أعظم حجة، فإنهم ما فعلوا ذلك ولا جسروا حتى قال - عليه السلام.\n\" لو تمنوا الموت ما قام رجل ممن مجلسه \"، فلم يجسروا أن يقولوا كاذبين: نحن نتمناه، ثم بين تعالى بقوله؟ ﴿وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ﴾⟪2:95⟫ قدرته على معاقبتهم تهددا لهم ...\n⟦1:267⟧"}, {"a": [96], "v": 1, "p": 267, "ev": 1, "ep": 269, "sid": 268, "t": "قوله - عز وجل -:\n﴿وَلَتَجِدَنَّهُمۡ أَحۡرَصَ ٱلنَّاسِ عَلَىٰ حَيَوٰةٖ وَمِنَ ٱلَّذِينَ أَشۡرَكُواْۚ يَوَدُّ أَحَدُهُمۡ لَوۡ يُعَمَّرُ أَلۡفَ سَنَةٖ وَمَا هُوَ بِمُزَحۡزِحِهِۦ مِنَ ٱلۡعَذَابِ أَن يُعَمَّرَۗ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ﴾⟪2:96⟫ الآية (96) سورة البقرة.\nالوجود يقال باعتباره بالحاسة، وباعتباره بالتخيل، وباعتباره بالفهم والعقل، ومتى قيل باعتباره بالعقل فعلى ضربين: متعب إلى مفعول واحد، ومعناه كمعنى عرفت، ومؤكد إلى مفعولين، ومعناه قريب من معنى علمت، والحرص أصله أن لا يرضى بالكفاية ويضاده القناعة، وأصله هن حرص القصار الثوب، والحارصة وهي شجة تشق الجلد، فالحرص كأنه مزيل للحياء والكرم عن النفس، وأصل الشرك مساواة اثنين فصاعدا في شيء كتجارة وزراعة وميرات [وشراك للفعل وشراك الخيط] معتبر فيه معنى الشركة، وكذا الشرك للطريق والحبالة للصائد، وصار الشرك متعارفا فيمن يثبت مع الله إلاها آخر أو يصفه بصفة على حد ما يوصف به شي من المكونات فيطلق تارة على من لم يكن من أهل الكتاب، كقوله: ﴿إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلصَّٰبِـِٔينَ وَٱلنَّصَٰرَىٰ وَٱلۡمَجُوسَ وَٱلَّذِينَ أَشۡرَكُوٓاْ﴾⟪22:17⟫، وهم الذين لا يقارون على بذل الجزية، ومرة يقال لأهل الكتاب لقولهم عزيز ابن الله والمسيح ابن الله [وقولهم اتخذ الله ولدا] ومرة يطلق على الربا ونحوه فروى أن أبا حنيفة- رحمه الله تعالي- قال لجعفر بن\nمحمد- رحمهما الله تعالى- من أين قال أبوك: الرياء شرك؟ فقال: من قول الله- عز وجل- ﴿فَمَن كَانَ يَرۡجُواْ لِقَآءَ رَبِّهِۦ فَلۡيَعۡمَلۡ عَمَلٗا صَٰلِحٗا وَلَا يُشۡرِكۡ بِعِبَادَةِ رَبِّهِۦٓ أَحَدَۢا﴾⟪18:110⟫.\nولما لم ينفك عامة الناس من تشبيه ما في أوصاف الله تعالى ومن رياء ما في عبادته، قصارى تعالى: ﴿وَمَا يُؤۡمِنُ أَكۡثَرُهُم بِٱللَّهِ إِلَّا وَهُم مُّشۡرِكُونَ﴾⟪12:106⟫ ...\n⟦1:268⟧\nوالعمر اسم لمدة عمارة البدن بالحياة، والعمارة قبيلة تحصل باجتماعهم العمارة، والمعمر المسكن مادام عامرة بسكانه، [والعومرة] صحب تدل على اجتماع عمارة، والعمري في العطية منة، والألف مشتق من الألفة، وهو ضم البعض إلى البعض، فالأعداد أحاد وعشرات ومئون وألوف، فالألف يألف أنواعها، وألسنة للعرب في أصلها طريقان من جعلها من الواو، كقولهم سنوات، وكأنها اسم لدوران الفلك، ولاعتبار الدوران فيها سمي المستقى عليها والمستقى بها [اسم لدوران الفلك] ساقية، ومنهم من يجعلها أمرا لها، فيقول: سانهته مسانهة فكأنها اسم لتغير الفصول الأربعة، ومنه قيل لسنة الطعام أي تغير، والزحزحة الإزالة عن المقر وقوله: ﴿وَمِنَ ٱلَّذِينَ أَشۡرَكُواْۚ﴾⟪2:96⟫ فمن المفسرين من يقول: تقدير الآية: \" ولتجدنهم وطائفة وكثيرا من المشركين أحرص الناس علي حياة، واستبعد ذلك بعض النحويين لحذف الموصول ترك الصلة، وقيل: تقديره \" وهم ﴿وَمِنَ ٱلَّذِينَ أَشۡرَكُواْۚ﴾⟪2:96⟫، فكأن قوله: ﴿وَمِنَ ٱلَّذِينَ أَشۡرَكُواْۚ﴾⟪2:96⟫ خبر ابتداء مضمر، أي هم في محبتهم للحياة من المشركين، وأكثر المفسرين على أنه عطف على معنى قوله ﴿أَحۡرَصَ ٱلنَّاسِ﴾⟪2:96⟫،\nفإن قيل: كيف قال ذلك والذين أشركوا من الناس؟ قيل: لما كان للمشركين فضل اختصاص في محبة الحياة الدنيا خصهم بالذكر بعد العموم تخصيص جبرائيل وميكائيل بعد ذكر الملائكة، وتخصيص النخل والرمان بعد الفاكهة،\nفإن قيل: فهلا قال: أحرص الناس والمشركين، أو من أحرص من الناس ومن المشركين ليكون الكلام على نمط واحد، قيل: إنما قال كذلك لمعنى اقتضاه، وهو أن أفعل يستعمل على وجهين، أحدهما مضافة إلى جملة هو بعضها نحو: هو أفضل الناس، ومعناه أن فضله زائد على جل المضاف إليه.\n⟦1:269⟧\nوالثاني: أن يذكر ب من، نحو: الإنسان أفضل من الأسد، ويرد أنه زائد على جميع الذكور، ويدلك على صحة هذا أنه إدا قيل: \" زيد أفضل الناس \"، وعني بالناس العموم لم يكن ذلك محالا، لأن يقتضي أن يكون أفضل من نفسه أيضا، إذ هو من الناس أو لا يكون منهم، فحيث ذكر تعالى الناس وأراد أنه زائد على جلهم أصناف، وحيث ذكر المشركين، عنى أنه زائد عليهم كلهم ذكر \" من \"، وإنما قال \" على حياة \" فنكرها، لأن الحياة التي يحرصون عليها هي حياة ما، وهي أحسن حياة \"، فكأنها لخستها وقلة وزنها ذكرها منكرة، وإنما الحياة المطلقة هي الحياة.\nالحقيقية التي وصف بها وللآخرة في قوله: ﴿وَإِنَّ ٱلدَّارَ ٱلۡأٓخِرَةَ لَهِيَ ٱلۡحَيَوَانُۚ﴾⟪29:64⟫، فأبان الله تعالي فرط حرصهم على الحياة الدنيا، وأن تمنيهم لها فوق تمني المشركين، إذ غاية تمنيهم للحياة ألف سنة، وبذلك يتداعون، ثم بين تعالى أن بقاءهم ألف سنة لا ينقذهم من عذاب الله إن ماله مدة فقصير، وإن طال، فكما قال الشاعر:\nأرى العمر كنزا ناقصا كل ليلة\n....\nوما تنقص الأيام والدهر ينقل"}, {"a": [97], "v": 1, "p": 269, "ev": 1, "ep": 270, "sid": 270, "t": "قوله تعالى:\n﴿قُلۡ مَن كَانَ عَدُوّٗا لِّـجِبۡرِيلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلۡبِكَ بِإِذۡنِ ٱللَّهِ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ وَهُدٗى وَبُشۡرَىٰ لِلۡمُؤۡمِنِينَ﴾⟪2:97⟫ الآية (97) سورة البقرة.\nالعدو التجاوز ومنافاة الالتزام، فتارة يعتبر بالقلوب، فيقال له العداوة، وتارة في المشيء، فيقال له العدو، وتارة في الإخلال بالعدالة في المعاملة، فيقال له العدوان، وتارة إما في المكان وإما في النسب، فيقال قوم عدي أي غربا، وجبريل فيه لغات، وإنما كثرت فيه اللغات لكونه معربا، وتقرأه كل [قبيلة] على حسب استحقاقه، فمنهم من لم يتحر فيه أبنية كلامهم ولا تخفيف اللفظ، ومنهم من خفف ولم\n⟦1:270⟧\nيراع البناء نحو جبريل، لأن \" فعليلا \" ليس في أبنيتهم، ومنهم من راعى رده إلي بناء كلامهم، فقال جبريل نحو قنديل، وعلى ذلك اختلفت اللغات في ميكائيل، ومنهم من قال جبر هو العبد وإيل هو الله، وإن ذلك كقولهم عبد الله، فإن ذلك لا يصح على حد كلام العرب، إذ لو كان كذلك لكان مضافا، والإذن: الإعلام بالرخصة، وقد يعبر عن الإعلام بالختم، ومعنى الآية أن اليهود زعمت أن جبريل عدوهم، فإنه لم يكن يأتي الأرض إلا بالصواعق، فقال تعالى: ﴿فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلۡبِكَ﴾⟪2:97⟫ أي أن جبريل نزل القرآن على قلبك بإذن الله ومصدقا لا تقدمه من كتب الله - عز وجل-، وهاديا ومبشرا للمؤمنين تنبيها على أنه لم يعاده ولا أحدا من أنبياء الله تعالى والصالحين من عباده، فليس من شأن الملك مخالفة الرب- عز وجل-، فإن هو عاداهما فلكونهم غير مؤمنين،\nإن قيل: كان الوجه أن يقال: \" فإنه نزله على قلبي \"، قيل: يجوز الأمران، فالحكاية تارة تعاد على اللفظ، نحو أن يقال: قل لهم الخبر عندي كذا وكذا، وتارة على المعنى، فيقال: \" قل لهم: الخبر عندك كذا \"، وعلى ذلك: ﴿قُل لِّلَّذِينَ كَفَرُواْ سَتُغۡلَبُونَ﴾⟪3:12⟫ وسيغلبون ويحشرون \"، ويجوز أن يكون قوله: قل خطابا لجبريل، كأنه قال: قل للنبي."}, {"a": [98], "v": 1, "p": 270, "ev": 1, "ep": 271, "sid": 271, "t": "قوله - عز وجل -:\nمن كان عدوا لله وملائكته ورسله وجبريل وميكال فإن الله عدو للكافرين} الآية (98) - سورة البقرة.\nقد يدل على تفسير هده الآية ما روي سأل عن جماعة من اليهود عن سبب امتناعهم من الإسلام، فقالوا: إن الملك الذي يأتي محمدا ...\nجبريل، وجبريل عدونا ولو أتاه ميكائيل لآمنا به، فإن ميكائيل صاحب كل رحمة، فقال عمر- رضي الله عنه- أنشدكم: أين جبرائيل وميكائيل من الله- عز وجل-؟\n⟦1:271⟧\nقالوا: جبرائيل عن يمينه، وميكائيل عن يساره، قال، فاشهدوا أن الذي هو عدو لمن عن يمينه عدو لمن على يساره، ومن هو عدو لهما فعدو لله - عز وجل-، فرجع عمر- رضي الله تعالى عنه، وقد أنزل الله هذه الآية تصديقا لقوله، ومنبها بذكر من ذكرهم والجمع بينهم أنما من عادى واحدا فقد عاداهم، فإنهم أولياء من والاه، وأعداء من عاداه، وبين بدلك أن اليهود إذا عادوا أحدهم فالله عدوهم، وحقيقة معاداة الإنسان لله والبعد عنه مخالفته في تحري الصدق في المقال والحق في الفعال وأن لا يستحق أن يوصف بشيء من أوصافه، نحو العادل والجواد والكريم والقريب منه والمحب له، هو أن لا يخالفه في ذلك، وإن يصح أن يوصف بتلك الصفات وتلك المعاني هي المقتضية لمعاداة أولياء الله والداعية لارتكاب المعاصي، فإذا: قول من قال معنى قوله: ﴿عَدُوّٗا لِّلَّهِ﴾⟪2:98⟫ عدوا لأولياء الله، أو قال: معناه: عاص لأمره، فإنه غير مخالف لما قلنا ..."}, {"a": [99], "v": 1, "p": 271, "ev": 1, "ep": 272, "sid": 272, "t": "قوله - عز وجل -:\n﴿وَلَقَدۡ أَنزَلۡنَآ إِلَيۡكَ ءَايَٰتِۭ بَيِّنَٰتٖۖ وَمَا يَكۡفُرُ بِهَآ إِلَّا ٱلۡفَٰسِقُونَ﴾⟪2:99⟫ الآية (99) سورة البقرة.\nعنى بالآيات القرآن وسائر المعجزات والدلالات التي أوضح الله- عز وجل - بها أمر النبي- عليه السلام-، وذكر أنه لا يجحد ذلك ولا ينكره إلا كل متناه في الكفر، والفاسق الخارج عن الطاعة، إما عن أصل الدين، وإما عن بعض الطاعات بارتكاب كبيرة، ولذلك قال- عز وجل- في إبليس: ﴿فَفَسَقَ عَنۡ أَمۡرِ رَبِّهِۦٓۗ﴾⟪18:50⟫، وقال فيمن يرمي المحصنات: ﴿وَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ﴾⟪24:4⟫، وقال: ﴿إِنَّ ٱلۡمُنَٰفِقِينَ هُمُ ٱلۡفَٰسِقُونَ﴾⟪9:67⟫ فبين الفاسق والفاسق بون ..\n⟦1:272⟧"}, {"a": [100], "v": 1, "p": 272, "ev": 1, "ep": 272, "sid": 273, "t": "قوله - عز وجل -:\n﴿أَوَكُلَّمَا عَٰهَدُواْ عَهۡدٗا نَّبَذَهُۥ فَرِيقٞ مِّنۡهُمۚ بَلۡ أَكۡثَرُهُمۡ لَا يُؤۡمِنُونَ﴾⟪2:100⟫ الآية (100) سورة البقرة.\n[النبذ] والطرح والإلقاء متقاربة، لكن النبذ أكثر ما يقال فيما ينسى، وعلى ذلك قول الشاعر:\nكنبذك نعلا أخلقت من نعالكا\nوقيل: صبي منبوذ إذا ألقته أمه فنسيته، واستعير للشراب الملقى المنسي إلى وقت إدراكه، والطرح أكثر ما يقال في المبسوط وما يجري مجراه، والإلقاء يعبتر فيه ملاقاة بين الشيئين أو بين الشيء ومكانه، ومعنى الآية: أنه لما بين تعالى أنه قد أنزل مالا يكفر به إلا كل فاسق بين لفظ الإنكار أن عادة بعض اليهود المذمومين تضيع العهد اللازم واطراحه، ثم بين أن عادتهم لا يؤمنون تنبيها أن أكثرهم وإن لم ينبذوا العهد جهارا لم يحص منهم الإيمان الذي هو معرفة ما يجب معرفته وفعل ما يجب فعله، بل اقتصروا على ظاهر القبول الذي لا يعتد به على الحقيقة ..."}, {"a": [101], "v": 1, "p": 272, "ev": 1, "ep": 273, "sid": 273, "t": "قوله - عز وجل -:\n﴿وَلَمَّا جَآءَهُمۡ رَسُولٞ مِّنۡ عِندِ ٱللَّهِ مُصَدِّقٞ لِّمَا مَعَهُمۡ نَبَذَ فَرِيقٞ مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ كِتَٰبَ ٱللَّهِ وَرَآءَ ظُهُورِهِمۡ كَأَنَّهُمۡ لَا يَعۡلَمُونَ﴾⟪2:101⟫ الآية (101) سورة البقرة.\nالرسول ههنا إن جعلته الرسالة أو جعلته النبي محمدا - صلى الله عليه وسلم - جعلته المسيح عليه السلام فالكل صحيح ومراد، وكذلك إن جعلت الكتابة ههنا التوراة أو جعلته القرآن فصحيح.\nلأن المنكر لأحدهما\n⟦1:273⟧\nفي حكم النكر للآخر، وقد بين الله تعالى أنه لما جاءهم بعد موسى رسول مطابق له، صار فريق مما اختصوا بعلم الكتاب نبذوا أحكام كتاب الله وراء ظهورهم، فصاروا كالجهلة، وهذا الفريق غير الفريق الأول، ولهذا لم يدخل فيه الألف واللام، وقد دل تعالى بالأيتين أن جل اليهود ثلاث فرق، فريق جاهر وأنبذ العهد، وفريق لم يجاهروا بذلك، لكنهم لم يؤمنوا به، وهم أكثرهم، وفريق أخر طرحوا حكم الكتاب عنادا، فصاروا في حكم الجهلة، وهذه القسمة عجيبة الشأن، فإن دافعي الحق ثلاثة أقسام،\nجاهل غير عالم بجهله، وهو الشرير الذي لا مداواة له، وإياه عنى بقوله.\n﴿أَوَكُلَّمَا عَٰهَدُواْ عَهۡدٗا نَّبَذَهُۥ فَرِيقٞ مِّنۡهُمۚ﴾⟪2:100⟫، وجاهل عالم بجهله، وهو الشاك وإياه عنى بقوله: ﴿بَلۡ أَكۡثَرُهُمۡ لَا يُؤۡمِنُونَ﴾⟪2:100⟫، ومعاند غير جاهل، وإياه عنى بقوله: ﴿نَبَذَ فَرِيقٞ مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ كِتَٰبَ ٱللَّهِ وَرَآءَ ظُهُورِهِمۡ كَأَنَّهُمۡ لَا يَعۡلَمُونَ﴾⟪2:101⟫ ووصف هذا الفريق بأن حكمهم حكم الجاهلين الذين هم فوق الموصوفين بأنهم لا يؤمنون، [وكل من دافع الحق لا ينفك من الأقسام الثالثة التي ذكرناهما والله أعلم] ..."}, {"a": [102], "v": 1, "p": 273, "ev": 1, "ep": 281, "sid": 274, "t": "قوله - عز وجل -:\n﴿وَٱتَّبَعُواْ مَا تَتۡلُواْ ٱلشَّيَٰطِينُ عَلَىٰ مُلۡكِ سُلَيۡمَٰنَۖ وَمَا كَفَرَ سُلَيۡمَٰنُ وَلَٰكِنَّ ٱلشَّيَٰطِينَ كَفَرُواْ يُعَلِّمُونَ ٱلنَّاسَ ٱلسِّحۡرَ وَمَآ أُنزِلَ عَلَى ٱلۡمَلَكَيۡنِ بِبَابِلَ هَٰرُوتَ وَمَٰرُوتَۚ وَمَا يُعَلِّمَانِ مِنۡ أَحَدٍ حَتَّىٰ يَقُولَآ إِنَّمَا نَحۡنُ فِتۡنَةٞ فَلَا تَكۡفُرۡۖ فَيَتَعَلَّمُونَ مِنۡهُمَا مَا يُفَرِّقُونَ بِهِۦ بَيۡنَ ٱلۡمَرۡءِ وَزَوۡجِهِۦۚ وَمَا هُم بِضَآرِّينَ بِهِۦ مِنۡ أَحَدٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمۡ وَلَا يَنفَعُهُمۡۚ وَلَقَدۡ عَلِمُواْ لَمَنِ ٱشۡتَرَىٰهُ مَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِنۡ خَلَٰقٖۚ وَلَبِئۡسَ مَا شَرَوۡاْ بِهِۦٓ أَنفُسَهُمۡۚ لَوۡ كَانُواْ يَعۡلَمُونَ﴾⟪2:102⟫\nالآية (102) سورة البقرة.\nتلا: يقال تارة في اتباع الغير إما بالجسم وإما بالحكم، ومصدره تلو، وتلو وتارة في اتباع الكلام، وإما بالقراءة وان ابالتدبر لمعناه، ومصدره تلاوة وعلى الأول قوله: ﴿وَٱلۡقَمَرِ إِذَا تَلَىٰهَا﴾⟪91:2⟫\n⟦1:274⟧\nوعلى الثاني قوله: ﴿يَتۡلُونَهُۥ حَقَّ تِلَاوَتِهِۦٓ﴾⟪2:121⟫، وتلا عليه كذب نحو روي عليه، وقال عليه، ﴿وَيَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ﴾ وأما السحر فقد اختلف في مائيته على ثلاثة أوجه، ولابد من تبيينه لينبني كلام الله عليه في هذه الآية وفي غيرها من الآيات في ذكر السحر، فالأول: ما ذهب إليه أكثر الجدليين، وهو أنه اسم خداع وتخييلات لا حقيقة له، وإنما اعتماد الساحرين على شغل القلوب بشعبذة صارفة للأبصار وتمتمة عميقة للأسماع ولصرف الأبصار، قال تعالى ﴿سَحَرُوٓاْ أَعۡيُنَ ٱلنَّاسِ وَٱسۡتَرۡهَبُوهُمۡ﴾⟪7:116⟫، ولشغل الأسماع بالنميمة، قال: فيتعلمون منهما ما يفرقون به بين المرء وزوجه، قالوا: ولهذا سمي البيانالرائق سحرا، والثاني ما ذهب إليه الأغشام من العوام وجماعة من الأشرار، وهو أنه اسم لفعل من قوته تغيير الطبائع ونقل الصور، كجعل الإنسان حيوانا أخر وذكروا من ذلك خرافات توصلت بها الملحدة والبراهمة إلى إبطال النبوات والمعجزات، والثالث ما ذهب إليه محصلة أهل الأثر وعامة\nالمتوسمين بالحكمة، وهو أنه عمل يقرب إلى الشيطان بمعونة منه، وذلك أن توقع الساحر وهمه على أمر يريد فعله بالغير لافظا بكلمات من الشرك ومادحا للشيطان مستعينا به والدي يحتاج إليه في معرفة ذلك مقدمة، وهي أن الجواهر المكلفة ضربان جسماني محسوس، وروحاني معقول، فكما أن الجسماني بالقول الجمل ثلاثة أقسام: خير، وشرير، ومتوسط، كذلك الروحاني، فالخير من الروحاني الأرواح المقدسة، وهي الملائكة، والشرير شياطين الجن والمتوسط مؤمنو الجن كمن نزل فيهم سورة\nالجن، ولا كانت الملائكة لا تواصل ولا تعاون إلا خيار الناس كل متأله نقي، وكل ناسك تقي متشبه بهم في المواظبة على العبادة والتقرب إلى الله - عز وجل- بالفعل والقول، كذلك الشياطين لا تواصل ولا تعاون إلا الأشرار من الناس كل مشرك خبيث عابد للشيطان معاند للرحمن، ولهذا قال: ﴿هَلۡ أُنَبِّئُكُمۡ عَلَىٰ مَن تَنَزَّلُ ٱلشَّيَٰطِينُ ۝ تَنَزَّلُ عَلَىٰ كُلِّ أَفَّاكٍ أَثِيمٖ﴾⟪26:221-222⟫، وقال: ﴿وَمَن يَعۡشُ عَن ذِكۡرِ ٱلرَّحۡمَٰنِ نُقَيِّضۡ لَهُۥ شَيۡطَٰنٗا فَهُوَ لَهُۥ قَرِينٞ﴾⟪43:36⟫، وقال: ﴿شَيَٰطِينَ ٱلۡإِنسِ وَٱلۡجِنِّ يُوحِي بَعۡضُهُمۡ إِلَىٰ بَعۡضٖ زُخۡرُفَ ٱلۡقَوۡلِ غُرُورٗاۚ﴾⟪6:112⟫\nإن قيل: لو أمكن الإنسان من جهة الشيطان الوقوف على الأخبار الغائبة والأفعال\n⟦1:275⟧\nالخارجة عن عادة البشر لكان يشبه طريق النبوة بطريق السحر، ولكن يجوز استغواء الساحر بسحره متصورا بصورة نبي، وذلك يؤدي إلى ما ادعاه ما في الزنديق على كثير من الأنبياء في أنهم كانوا سحرة معاونين من قبل الشيطان، لا من قبل الرحمن - عز وجل -، قيل: الفرق بين ما يكون من فعل السحرة وبين ما يكون من الأنبياء لا يخفى على متنبه في المعرفة ومتدرج في أدنى منزلة من الحكمة، فإن تأثير السحر لا يكون إلا في فساد جزئي من كل مشرك خبيث في نفسه شرير في طبعه متدنس في بدنه، ولذلك أكثر ما يقع في حيض النساء وعبدة الأصنام وضعاف العقول وفي الأمكنة القذرة، وأكثر تأثيرهم في مجالسهم، ثم لا يكون في الندرة، ومتى قوبل بالاستعاذة بالله تعالى وبذكره بطل سلطانه، فأما ما كان من الأنبياء عليهم السلام، فلا يحصل إلا من كل مؤمن محصن الإيمان مقدس في نفسه خير في طبعه طاهر في بدنه [ويكون تأثيره] في أولي العقول الراجحة والأفهام البارعة، ويزداد بازدياد التقرب إلى الله تعالى، وذلك ظاهر لمن ألقى السمع وهو شهيد، ولو لم يكن للسحر حقيقة لا أعظم الله أمره في قوله: ﴿وَجَآءُو بِسِحۡرٍ عَظِيمٖ﴾⟪7:116⟫، ولما أمروا بالتعوذ من شر النفاثات في العقد، ولو كان كما قال الجدليون لما ورد والشرائع بقتل السحرة ونفيهم عن بلاد الإسلام، ولما أجرى مجرى الشرك حتى قال بعض الفقهاء: لا تقبل توبتهم كالمستسر بالكفر، والنميمة والخديعة لا تستحق بها هذه العقوبة، فإن قالوا فالذي هو كفر هو ما تقول العامة إن الساحر يطير بلا جناح، ويكفي البيضة والمكنة، فيبلغ في أقصر مدة إلى بلد بعيد، قيل: مدعى دلك ومصدقه سخيفان يضحك منهما، ولا خلاف أن بذلك لا يستحقان الارتداد والقتل، وإنما يستحق القتل إذا ادعى قتل الإنسان بسحره على شرائط مخصوصة على قول بعض الفقهاء أو ادعى ما ينبئ عن صريح كفر، وقد أنكر الجدليون ما روي في ذلك من الأخبار الصحيحة والآثار الواضحة كنحو ما روي أن اليهود سحرت رسول الله - صلى الله عليه وسلم - فقال - عليه السلام: \" أتاني ملكان، فقعد أحدهما عند رأسي، والآخر عند رجلي، فقال أحدهما: ما بالرجل فقال الأخر: مطبوب، قال: ومن طببه؟ قال: بنات لبيد بن\n⟦1:276⟧\nأعصم اليهودي \"، فبماذا قال في مشط ومشاطه، وجف طلعه ذكر في بئر ذوى أروان، فبعث من أخرجه وحل عقده، فكلما حل حل عقده، وجد لذلك خفة كأنما أنشط من عقال \" قالوا: إن ذلك إن قلنا بصحته لكان يقدح في نبوته، وليس الأمر على ما ظنوه لما تقدم، ولأن تأثير السحر لم يكن في النبي - عليه السلام - من حيث ما هو نبي، وإنما كان في بدنه من حيث هو إنسان وبشر، وكما كان يأكل ويتغوط ويشرب ويمشي ويقعد ويغضب ويشتهي ويمرض ويصح من حيث هو بشر لا من حيث هو نبي، وإنما كان ذلك قادحا في النبوة لو وجد للسحر تأثير في أمر يرجع إلى النبوة، ثم كون النبي - عليه السلام - معصوما من الشيطان لا يقتضي أن لا يؤثر في بدنه ذلك تأثيرا صغيرا لا يقدح فيه من حيث ما هو نبي، فقد كأن تأثير ذلك في جزء من بدنه تأثيرا محسوسا لم يتعده إلى زوال عقله ولا إلي إفساد نفسه، كما أن جرحه وكسر ثناياه يوم أحد لم يقدح فيما ضمن الله له من عصمته، حيث قال: ﴿وَٱللَّهُ يَعۡصِمُكَ مِنَ ٱلنَّاسِۗ﴾⟪5:67⟫، وكما لا اعتداد بما يقع في الإسلام من ارتداد أهل بلد أو غلبة المشركين على بعض النواحي فيما ذكر من كمال الإسلام بقوله: ﴿ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ﴾⟪5:3⟫ ومن أثبت كليات الحقائق بإثبات جزئياتها لم يسعفه في قياسه لدى التحصيل مقدمته ولا يثبت به في المقامات قدمه، وأما متصرفات لفظ السحر، فقد كثرت، وذاك إنه من حيث يتصور تارة دقته وتارة، حسنه وتارة فتنته، وتارة خبثه وشرارته استعمل في كل ذلك لفظه بحسب تصور كل واحد من ذلك، فسمي الشعبذة سحرا ومنه قوله: ﴿سَحَرُوٓاْ أَعۡيُنَ ٱلنَّاسِ﴾⟪7:116⟫، والكلام الرائق سحرا، ومنه قيل: (إن من البيان لسحرا)، والعين الفاتنة ساحرة، والعالم ساحرا، [وعلى ذلك حمل قوله: ﴿وَقَالُواْ يَٰٓأَيُّهَ ٱلسَّاحِرُ ٱدۡعُ لَنَا رَبَّكَ﴾⟪43:49⟫، والفعل الدقيق سحرا] حتى قالت الأطباء: الطبيعة ساحرة، وسمي الغذاء\n⟦1:277⟧\nسحرا من حيث يدق تأثيره، قال: وتسحر بالطعام وبالشراب والسحر الرئة، فيجوز أنه سمي بذلك اعتبارا بدقة تأثيره في ترويحه القلب بإيصال النفس (البارد إليه) إخراج الحارمنه، فكأنه ساحر في فعله ذلك، وقوله: ﴿إِنَّمَآ أَنتَ مِنَ ٱلۡمُسَحَّرِينَ﴾ قبل من المخلوقين وحقيقته من المجعول له سحر، أي من الحيوان، وقيل فيه، وفي قوله: ﴿إِن تَتَّبِعُونَ إِلَّا رَجُلٗا مَّسۡحُورًا﴾، أي معه رأي من الجن والفتنة: اختيار بتعذيب، ولما انطوى معناها على الأمرين استعملت في كل واحد منهما مفردة نحو قوله: ﴿ذُوقُواْ فِتۡنَتَكُمۡ﴾⟪51:14⟫ أي عذابكم وفتنت الذهب إذا اختبرته بالنار، وقوله: ﴿وَلَقَدۡ فَتَنَّا قَبۡلَهُمۡ قَوۡمَ فِرۡعَوۡنَ﴾⟪44:17⟫ يحتمل الوجهين، والآية معطوفة على ما تقدم من ذكر اليهود، وهي منطوية على أمرين: ذم اليهود في تحري السحر وإيثاره وتبرئة لسليمان - عليه السلام - مما نسبوه إليه، وذلك أنه روى أن الشياطين من الإنس والجن دفنوا تحت كرسي سليمان عليه السلام شيئا من السحر، فلما مات عليه السلام أخرجوا ذلك، وادعوا أنه كان يتحرى ما يتحراه سحرا منها فذكر الله تعالى أن بعض اليهود اتبعوا ما تخرصه الشياطين على ملك سليمان، ونزه سليمان عن الكفر وما نسب إليه من السحر، وذكر أن الشياطين هم المستحقون لذلك، واختلف في قوله: ﴿وَمَآ أُنزِلَ عَلَى ٱلۡمَلَكَيۡنِ﴾⟪2:102⟫ فقيل فيه ثلاثة أقوال:\nالأول: أن ما جرى معطوف على قوله ﴿مُلۡكِ سُلَيۡمَٰنَۖ﴾⟪2:102⟫ ومعناه : كذبوا على ملك سليمان وعلى ما أنزل على الملكين والثاني: أن ما نفى وعلى القولين: قيل لم يعلم الملكان السحر، بل كانا ينهيان عنه ﴿حَتَّىٰ يَقُولَآ إِنَّمَا نَحۡنُ فِتۡنَةٞ﴾⟪2:102⟫ أي حتى بلغ من نهيهما عن ذلك أنهما كانا يقولان إنما نحن فتنة، أي مفتونون بأن نعلم السحر وذلك مستبعد من حيث اللفظ، فإنه إنما يقال: فلان لا يفعل كذا حتى إنه يقول كذا على سبيل الاستئناف، ولا يقول حتى يقول، وقال هذان القائلان معنى (ويتعلمون منهما) أي\n⟦1:278⟧\nمن السحر والكفر، وقد جرى ذكر السحر صريحا، وذكر الكفر ضمنا في قوله، كفروا، والثالث قول أكثر المفسرين إن (ما أنزل) نصب معطوف على قول السحر، ومعناه علم السحر وكيفية تعاطيه وقوله \" منهما \" راجع إلى الملكين، وكان تعليمهما ذلك ليحترز به، لا ليتعاطى فعلها ولهذا كانا يقولان ﴿إِنَّمَا نَحۡنُ فِتۡنَةٞ فَلَا تَكۡفُرۡۖ﴾⟪2:102⟫، والذي أنكره من يذهب إلى التقديرين الأولين هو لظنه أن علم السحر محظور كفعله، وليس الأمر على ما ظن، وذاك لما قد ثبت أن الحكمة معرفة الصدق من الكذب في الأقوال والخير من الشر في الأمور ليتحرى الصدق والخير ويتجنب الكذب والشر، فمعرفة الكذب.\nوالشر إذا واجبة كوجوب معرفة الصدق والخير، بل لا يتم معرفة أحدهما إلا بالآخر كما قد تبين أن المعرفة بالمتضادين واحد، وإن كان معرفتهما لازمة، فتعريفهما واجب، وإنما المستقبح تعاطي الكذب والقبيح، فإذا كان كذلك فلا ضير أن يبعث الله تعالى من قبله في وقت يكثر فيه الاستغواء بالسحر هن ينبه على وجه احتياله، فتزول عن الناس الشبهة، ثم إن استعان شرير به على تعاطي شر، فهو كالاستعانة بتعلم الفقه وتعاطي العبادات لاستغواء الناس، فما من شي من المعادن أو من المعارف والعلوم نسخ في هذه الدار مصلح لخير إلا ويمكن استعماله في شر، ومن لم يتمسك فيما يتحراه بالطاعة وقع في المعصية أو الكفر، وأما هاروت وماروت فالظاهر أنهما. كانا الملكين، وقيل: كانا رجلين سميا ملكين اعتبارا بصلاحهما ولهذا قرأ بعض القراء ﴿وَمَآ أُنزِلَ عَلَى ٱلۡمَلَكَيۡنِ﴾⟪2:102⟫ اعتبارا بملكهما، وقال بعض المفسرين إن الملكين ليسا بهاروت وماروت، وإنما هما شيطانان من الجن والإنس وجعلهما نصبا في اللفظ بدلا من الشياطين بدل البعض من الكل كقولك: القوم قالوا كذا زيد وعمرو، قال: ويكون قولهما: (وإنما نحن فتنة) كقول الخليع لغيره: لا تعيرني فإني خليع فاسق، ويكون قوله: ﴿وَمَآ أُنزِلَ عَلَى ٱلۡمَلَكَيۡنِ﴾⟪2:102⟫ نفقا اعتراضا بين البدل والمبدل منه، وروى بعض من جعلهما ملكين أنهما كانا صيرا على صورة الآدميين وركب منهما الشهوة، وأنهما تعرضا لامرأة يقال لها زهرة فحملتهما على شرب الخمر وارتكاب المحظور ثم صعدت إلى السماء، فقد استسخف جماعة الجدليين قائل هذا الحديث وعدوه خرافة ينره العاقل سمعه عن سماعه، وذكر بعض الناس أن ذلك رمز منقول عن\n⟦1:279⟧\nكلام القدماء، وكان عادتهم أن يرمزوا بكثير من العلوم قال: وهذا من رموزهم، وهو أنه كان عادتهم إذا أرادوا تبيين اختصاص كل نجم بفعل يختص به جعلوه بصورة متعاطي الفعل الخاص به ويقول: إنه فعل كذا وقال كذا، ولما كان من شأن الزهرة على ما يدعون حمل الإنسان على تعاطي الغزل واللهو واللعب والشرب كنوا عنه بذلك، وعلى ذلك قالوا: الأفعال الزهرية كناية عن الغزل واللعب، وعلى ذلك فعلوا في سائر النجوم حتى جعلوا لها صورا مصورة في الكتب على هيأت المتعاطين الصناعات المختصة بطبعها والله أعلم بذلك، وقوله تعالى: ﴿فَيَتَعَلَّمُونَ مِنۡهُمَا مَا يُفَرِّقُونَ بِهِۦ بَيۡنَ ٱلۡمَرۡءِ وَزَوۡجِهِۦۚ﴾⟪2:102⟫ قيل: عني به الرجل وامرأته، وقيل: عني به الإنسان وقرناءه وأصدقاءه امرأة كانت أو غيرها، نحو قوله: ﴿ٱحۡشُرُواْ ٱلَّذِينَ ظَلَمُواْ وَأَزۡوَٰجَهُمۡ﴾⟪37:22⟫ إشارة إلى قوله تعالى: ﴿إِنَّمَا يُرِيدُ ٱلشَّيۡطَٰنُ أَن يُوقِعَ بَيۡنَكُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ﴾⟪5:91⟫، وقوله: ﴿فَيَتَعَلَّمُونَ﴾⟪2:102⟫ معطوف على ضمن ما تقدم، كأنه قال: يعلمون فيتعلمون، وقوله: ﴿وَمَا هُم بِضَآرِّينَ بِهِۦ مِنۡ أَحَدٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ﴾⟪2:102⟫ الإذن قد يقال في الإعلام بالرخصة، وقد يقال للعلم، ومنه أذنته بكذا، ويقال في الأمر الجسيم، وينبغي أن يعلم أن الإذن في الشيء من الله تعالى ضربان، أحدهما: الإذن لقاصد الفعل في مباشرته نحو قولك: أذن الله لك أن تصل الرحم، والثاني: الإذن في تسخير الشيء على وجه تسخير السم في قتله من يتناوله والترياق في تخليصه من أذيته، فإذن الله تعالى في وقوع التسخير وتأثيره من القبيل الثاني، وذلك هو المشار إليه بالقضاء، وعلى هذا يقال: الأشياء كلها بإذن الله وقضائه، ولا يقال: الأشياء كلها بأمره ورضاه، والضر ما يعوق الإنسان عن فعل الخير سواء كان ذلك مما يعرض في بدنه، أو كان شيئا خارجا منه، والنفع ما يسهل سبيل الإنسان إلى الخير، ومن قال: النفع هو اللذة، فإنما اللذة بعض النفع، فقد يكون الشر نافعة، ولا يكون لذيذا،\nإن قيل: كيف قال: ﴿مَا يَضُرُّهُمۡ وَلَا يَنفَعُهُمۡۚ﴾⟪2:102⟫ وما يضر يعلم أنه لا\nينفع؟ قيل: إن ذلك من وجه ووجه، فقد يكون الشيء نافعة من وجه وضارا من وجه، وتعلم السحر كان\n⟦1:280⟧\nنفعا لو احترزوا بمعرفته عمن يغوى، فلم ينتفعوا به من هذا الوجه واستضروا به لاستعمالهم إياه في غير الحق ولقد علموا أن من استبدل ما جاءت به الشياطين من السحر بالحق أن لاحظ له في الآخرة.\nقوله - عز وجل -:\n﴿وَلَبِئۡسَ مَا شَرَوۡاْ بِهِۦٓ أَنفُسَهُمۡۚ لَوۡ كَانُواْ يَعۡلَمُونَ﴾⟪2:102⟫ الآية (102) سورة البقرة.\nويصح أن يكون معطوفا على المعلوم، وهو قوله: ﴿لَمَنِ ٱشۡتَرَىٰهُ﴾⟪2:102⟫ ويصح أن يكون استئنافا حكما به، وجواب قوله: ﴿لَوۡ كَانُواْ يَعۡلَمُونَ﴾⟪2:102⟫ محذوف.\nإن قيل: كيف أثبت لهم العلم في أول الكلام ونفى عنهم في أخره؟ فالجواب في ذلك من أوجه ..\nالأول: أن العلم المثبت لهم هو العقل الغريزي، وما جعله لهم بصيغته، والمنفي عنهم هو المكتسب الذي هو من جملة التكليف، والثاني: أن المثبت لهم هو العلم بالجملة، والمنفي عنهم هو العلم بالتفصيل، فقد يعلم الإنسان مثلا قبح الشيء ثم لا يعلم أن فعله قبيح، فكأنهم علموا أن شرى النفس بالسحر مذموم، لكن لم يتفكروا في أن ما يفعلونه هو من حملة ذلك القبيح، والثالث: أنهم علموا عقاب الله، لكن لم يعلموا حقيقة عقابه وشدته، والرابع: أن معنى قول ﴿لَوۡ كَانُواْ يَعۡلَمُونَ﴾⟪2:102⟫ يعملون به، لأن من لا\nيعمل بما يعلم فهو في حكم من لا يعلم.\n⟦1:281⟧"}, {"a": [103], "v": 1, "p": 281, "ev": 1, "ep": 281, "sid": 282, "t": "قوله - عز وجل -:\n﴿وَلَوۡ أَنَّهُمۡ ءَامَنُواْ وَٱتَّقَوۡاْ لَمَثُوبَةٞ مِّنۡ عِندِ ٱللَّهِ خَيۡرٞۚ لَّوۡ كَانُواْ يَعۡلَمُونَ﴾⟪2:103⟫ الآية (103) - سورة البقرة.\nالثؤوب: رجوع الشيء إلى حالة شبيهة بالحالة الأولى، يقال: ثاب الحوض إذا امتلاء بعد فراغه عقيب امتلائه، والثوب لتصوره بصورة القطن لاجتماع أجزائه بعد تفرقها بالغزل، والثيب من النساء لعودها إلى الأيمة، والتثويب في الصوت ترديده، والثواب والمثوبة في الخير تحصيل نفع يثوب إليه بإحسانه، ومعنى الآية: لو أمن الذين يتعلمون السحر واتقوا لأثيبوا وكان ذلك خيرا لهم، ولو علموا لظهر لهم ذلك، وجواب لو [الأولى] ما دل عليه لمثوبة وتقديره: لأثيبوا، تقول: لو أتاني زيد لإكرامي خير له، ولا تقول له أتاني زيد لعمرو منطلق، إذ لم يدل لفظ عمرو على فعل، وجواب لولا يكون إلا فعلا، أو ما دل عليه، ومن النحويين من أجاز ذلك إذا دل الخبر على فعل ..."}, {"a": [104], "v": 1, "p": 281, "ev": 1, "ep": 282, "sid": 282, "t": "قوله - عز وجل -:\n﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقُولُواْ رَٰعِنَا وَقُولُواْ ٱنظُرۡنَا وَٱسۡمَعُواْۗ وَلِلۡكَٰفِرِينَ عَذَابٌ أَلِيمٞ﴾⟪2:104⟫\nالآية (104): سورة البقرة:\nالراعي: حفظ الغير في أمر يعود بمصلحته، ومنه: رعي الغنم، ورعي الوالي الرعية، وعنه نقل: أرعيته سمعي، وتشبيها برعي الغنم قيل: رعيت النجوم إذا راقبتها، وكان يقال للنبي- عليه السلام-[راعنا] أي استمع إلينا واحفظنا، فقالت اليهود: راعنا تعريضا به من الرعونة، فلما عوتبوا قالوا: إنما نقول مثل ما يقول المسلمون، فنهوا عن ذلك، وقيل لهم: قولوا بدل ذلك انظرنا، وذلك معناه معنى راعنا، وقد نبه على ذلك بقوله- عز وعلا-: ﴿مِّنَ ٱلَّذِينَ هَادُواْ يُحَرِّفُونَ ٱلۡكَلِمَ عَن مَّوَاضِعِهِۦ﴾⟪4:46⟫ الآية، وقوله: ﴿وَٱسۡمَعُواْۗ﴾⟪2:104⟫: يجوز أن يكون من جملة ما أمروا لن يقولوا مع قولهم \" انظرنا \" ويجوز أن يكون ذلك استئناف أمر من الله تعالى بامتثال ما أمرهم به، وقيل: إنما نهوا عن قولهم: \" راعنا \" لكونه\n⟦1:282⟧\nمفاعلة متضمنة لمعنى المساواة بين المخاطب والمخاطب، فأمروا بتوقيره، كما قال ﴿لَّا تَجۡعَلُواْ دُعَآءَ ٱلرَّسُولِ بَيۡنَكُمۡ كَدُعَآءِ بَعۡضِكُم بَعۡضٗاۚ﴾⟪24:63⟫، وكقوله: ﴿وَلَا تَجۡهَرُواْ لَهُۥ بِٱلۡقَوۡلِ كَجَهۡرِ بَعۡضِكُمۡ لِبَعۡضٍ﴾⟪49:2⟫، وذلك عن ابن عباس- رضي الله عنه-، وروي عن مجاهد أن معناه: لا تقولوا خلافا ويكون من الرعن، وأسترذل هذا الوجه، لأنه لو كان كما قال لكان في القراءة رعنا بالتنوين."}, {"a": [105], "v": 1, "p": 282, "ev": 1, "ep": 283, "sid": 283, "t": "قوله - عز وجل -:\n﴿مَّا يَوَدُّ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَلَا ٱلۡمُشۡرِكِينَ أَن يُنَزَّلَ عَلَيۡكُم مِّنۡ خَيۡرٖ مِّن رَّبِّكُمۡۚ وَٱللَّهُ يَخۡتَصُّ بِرَحۡمَتِهِۦ مَن يَشَآءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ﴾⟪2:105⟫ الآية (105) - سورة البقرة.\nالود: محبة الشر مع تمنيه، ولما كان لهما استعمل في كل واحد منهما، فقيل: وددت فلانا إذا أحببته، وددت الشيء إذا تمنيته، وأصل الاختصاص الخصاص وهو فرجة بين الشيئين، ومنه الخص لبيب من قصب لما فيه من الفرج، وسمي انثلام الحال خصاصا وخصاصة على التشبيه، كما سمي انثلاما واختلالا وشعبا، وخصصت فلانا وخصني أوليته خصاصي نحو خللته، وقولهم: وقفتهم على عجزي ونحري، وخصان الرجل خلانه، ثم جعل الخاص مقابلا للعام في التعارف، وسبب نزول هذه الآية أن جماعة من اليهود كانوا يظهرون مودة المسلمين، ويزعمون أنهم يودون لهم الخير، فأكذبهم الله تعالى في ذلك، ونفي ما أدعوه وكان المسلمون يوالونهم ويركنون إليهم، فأكذبهم الله تعالي في ذلك [ونفى ما ادعوه] ونهاهم تعريضا عن موادتهم، كما قال: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلَّذِينَ ٱتَّخَذُواْ دِينَكُمۡ هُزُوٗا وَلَعِبٗا مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَٱلۡكُفَّارَ أَوۡلِيَآءَۚ﴾⟪5:57⟫\nإن قيل: فلم قال: \" ولا المشركين \" وذلك يقتضي أن المشركين ضربان، كافر، وغير كافر كما أن أهل الكتاب ضربان؟ قيل: إن \" من \" في قوله ﴿وَمِنۡ أَهۡلِ ٱلۡكِتَٰبِ﴾⟪3:75⟫ للتبيين ﴿فَٱجۡتَنِبُواْ ٱلرِّجۡسَ مِنَ ٱلۡأَوۡثَٰنِ﴾⟪22:30⟫، فإذا كان كذلك، فالذين كفروا هم أهل الكتاب، فجاز أن يقال: ﴿وَلَا ٱلۡمُشۡرِكِينَ﴾⟪2:105⟫ عطفا على لفظ أهل الكتاب، وجاز أن يقال ﴿وَلَا ٱلۡمُشۡرِكِينَ﴾⟪2:105⟫⟦1:283⟧ عطفا على الذين، ولو قرئ به لجاز، كما جاز، وقوله: ﴿مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ﴾ والكفار النصب والجر جميعها ومن في قوله: ﴿مِّنۡ خَيۡرٖ﴾⟪2:105⟫ لاستغراق الجنس، وبين بأخر الآية أنه وإن اختص برحمته بعض الناس، فليس ذلك لضيق فضله، بل فضله عظيم، ورحمته [تسع كل شيء وإنما يسع رحمته] ضربان، أحدهما يصل إليه كل من شاء الوصول إليه من العباد\nبتمكين الله إياه وضرب يخص تعالى به بعض عباده لا يعرفه في ذلك .."}, {"a": [106], "v": 1, "p": 283, "ev": 1, "ep": 288, "sid": 284, "t": "قوله - عز وجل -:\n﴿مَا نَنسَخۡ مِنۡ ءَايَةٍ أَوۡ نُنسِهَا نَأۡتِ بِخَيۡرٖ مِّنۡهَآ أَوۡ مِثۡلِهَآۗ أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ﴾⟪2:106⟫\nالآية (106) - سورة البقرة.\nقد تقدم الكلام في مناهية النسخ والفرق بينه وبين التخصيص في صدر الكتاب، والنسخ في اللغة إزالة الصورة عن الشر وإثباتها في غيره كنسخ الظل للشمس، ثم يقال في إزالة الصورة من غير إثباتها في غيره نحو قوله تعالى: ﴿فَيَنسَخُ ٱللَّهُ مَا يُلۡقِي ٱلشَّيۡطَٰنُ ثُمَّ يُحۡكِمُ ٱللَّهُ ءَايَٰتِهِۦۗ﴾⟪22:52⟫، ويقال أيضا في إثبات مثل تلك الصورة في الغير من غير إزالتها سكن الأول كنسخ الكتاب وأصحاب التناسخ زعموا.\nأن النفوس تنتقل من هيكل إلى هيكل، فإن كانت محسنة انتقلت إلى هيكل متنعمة فيه، وإن كانت مسيئة فإلى هيكل معذبة فيه، وليس الإنسان الأمر بالترك المؤدي إلى النسيان، وليس كل متروك يقال له منسئ، وقرئ ننسأها من النسئ، وهو تأخير الشيء عن وقته أو عن هيئته، فمما هو بالوقت قولهم:\nنسأت في ظمي الإبل، ونسأ الله في أجلك، و \" نسأت المرأة \" تأخر وقت حيضها، وأنسأت فلانا البيع، وقوله تعالى: ﴿إِنَّمَا ٱلنَّسِيٓءُ زِيَادَةٞ فِي ٱلۡكُفۡرِۖ﴾⟪9:37⟫ ومما هو بالهيئة نسأت الإبل عن الحوض،\n⟦1:284⟧\nونسأتها في السير، ومنها المنسأة للعصا التي يطرد بها، وحمل المفسرون النسخ والإنساء على وجهين: أحدهما أن النسخ هو إزالة الحكم من غير اللفظ، أو الحكم مع اللفظ، والإنسان مقابله، وهو أن لا ينسخ بل يقر، والثاني: أن النسخ إزالة الحكم فقط ثبات اللفظ أو لم يثبت، ولهذا قال الفقهاء:\nإن النسخ لا يكون إلا في معنى الأمر والنهي معني الخبر والإنشاء يكون في الإخبار وفي الأمر والنهي، لكن في الخبر معناه لا يزول وإن زال اللفظ، وقد يستعمل أحد اللفظين مكان الأخر، فمن هذا ما روت عائشة- رضي الله تعالى عنها- أنه نزل في قصة أهل بئر معونة قرآن منه: (بلغوا قومنا) أن قد لقينا ربنا فرضي عنا وأرضانا)، ثم نسخت، ففيه دلالتان:\nإحداهما أن قوله: (لقينا ربنا) إخبار، وقت سمته نسخا، والثانية: أنها استعملت النسخ في رفع التلاوة دون المعنى، وعلى ذلك ما روي أنه كان فيما أنزل الله: (لو أن لابن أدم واديين من مال لابتغى إليهما ثالثا، ولا يملا جوف ابن أدم إلا التراب ويتوب الله على من تاب)، ثم نسخ وذلك خبر، وقيل: الكلام في تأويل الآية أن يذكر ما يكشف خطأ اليهود وشرذمة من المسلمين أنكروا النسخ زاعمين أن ذلك هو المبدأ، ولا يفعلن إلا من يجهل العواقب ويتجدد له رأي بعد رأي، فيقال وبالله التوفيق ...\n\" إن لله تعالى خلفاء في الأرض مستخلفين فيها ومستعمرين فيها لنتوصل بذلك إلى مجاورته والقرب منه بحياة لا موت بعدها، وغنى لا حاجة معه، وقدرة لا يعتورها عجز، ولا سبيل إلى ذلك إلا باكتساب الصحة في النفس، وصحتها أمران: العلم والعمل، أما العلم: فمعرفة الصدق من الكذب، والجميل من القبيح، والخير من الشر، وأما العمل: فتحري الصدق في المقال والجميل في الفعال وتجنب ضديهما، وكما لا سبيل إلى استفادة صحة البدن إلا بطبيبين، أحدهما من داخل وهي القوة\n⟦1:285⟧\nالتي سخرها الله تعالى لاستدعاء الطعام وهضمه ودفعه، والثاني من خارج، وهو الذي يتلف من هذه القوة إذا اختلت، كذلك لا سبيل إلى استفادة صحة النفس إلا بطبيبين أحدهما من داخل وهو العقل، والثاني من خارج وهو النبي وكما أن أدوية البدن وأغذيته العقاقير والأطعمة، فأدوية النفس الأعمال الشرعية والآداب الخلقية، وكما أن طبيب البدن قد يغير الأغذية والأدوية التي يتوصل بها إلي استفادة الصحة واستبقائها لاختلاف الأزمنة، كذلك الأنبياء من قبل الله قد يغير الأعمال الشرعية التي هي مصلحة للأنفس حسب ما يعرف الله من مصالحها، فكما يكون الشيء دواء للبدن في وقت، ثم يكون داء في وقت غيره، ذلك الأعمال قد تكون مصلحة في وقت، مفسدة في وقت، ولكون الشريعة طلبا للنفوس قال المسيح: \" إنما أنا طبيب المرضى \"، وروى: أن العالم طبيب الدين، والدنيا داؤه فإذا جر الطبيب الداء إلى نفسه، فكيف يداوي غيره، ومما يبين جوار النقل من حكم إلى حكم نقل الله تعالى الأشياء حال إلى حال حتى ينتهي إلى أقصى الكمال كمال الإنسان من مبدأ إلى منتهى عمره وذلك من حين النطفة، ثم العلق، ثم المضغة، ثم كونه جنينا، ثمة طفلا، ثم ناشئا وكهلا وشيخا وهرما، ثم ما نبه النبي عليه السلام بقوله: \" إن لكم معالم، فانتهوا إلى معالمكم، وإن لكم نهاية فانتهوا إلي نهايتكم \"، ولو كان نقل الشرع من حال إلى حال قبيحا لكان بعثة موسى ونقله اليهود عن بعض ما كانوا عليه قبيحا، وأماما حكوه عن موسى عليه السلام- أنه قال لبني إسرائيل هذه الشريعة لازمة لكم أبدآ مادامت السموات والأرض، فلفظ محتمل وفي إتيانه على وجه محتمل حكمة عظيمة قد ذكرها الحكماء، وهي أن من عادة العامة وغريزتها أن لا ينقاد كل الانقياد لراع أو رئيس إذا علموا كونه مصروفا من بعد، بل يستوهنون أمره ويضعفون حاله، فإذا واجب أنما لا يعلموا بأن أمره غير ممتد، وأن لا يبين ذلك إلا للأعيان الذين لا يكون منهم مفسدة، فلهذا كانوا الألفاظ الواردة من الأنبياء عليهم السلام محتملة أن شريعتهم على التأييد، فإن قيلت إن ذلك يؤدي إلى أن يقال في\n⟦1:286⟧\nنبينا- عليه السلام- إنا لم نعلم كونه دينه- عليه السلام- على التأييد من قوله فقط، بل علمنا ذلك قول من قوله ببرهان، وهو أن دينه بالاعتبار العقلي وسحل كما وصفه تعالى بقوله: ﴿جَعَلۡنَٰكُمۡ أُمَّةٗ وَسَطٗا﴾⟪2:143⟫ وأنه مصون عن الإفراط والتفريط والوسط الذي هذا صفته هو الحق الذي قال تعالى فيه: ﴿فَمَاذَا بَعۡدَ ٱلۡحَقِّ إِلَّا ٱلضَّلَٰلُۖ﴾⟪10:32⟫، ولشرح دلك موضع غير هذا وبالله التوفيق، وأما معنى الآية، فعلى قول من يجعل الإنشاء مقابلا للنسخ قال: لما أنكرت اليهود تحليل الله الشيء في وقت [وتحريمه في وقت] بين الله تعالى أن جميع ما في التوراة، والكتب المتقدمة ضربان إما حكم قد نسخ فأتى بما هو خير أي أنفع لكم، أو يترك فلم ينسخ وأتى في القرآن بمثله، أي جمعناه في لفظ آخر، فيكون بقوله: ﴿بِخَيۡرٖ مِّنۡهَآ﴾⟪2:106⟫ راجعا إلى النسخ وبمثلها إلى الإنسان،\nفإن قيل: إن الذي ترك ولم ينسخ ليس هو مثله بل هو هو، فكيف قال بمثلها؟ قيل: الحكم الذي أنزل في القرآن وكان ثابتا في الشرع الذي\nقلنا يصح أن يقال هو هو إذا اعتبر بنفسه ولم يعتبر بكسوته التي هي اللفظ، ويصح أن يقال: هو مثله إذا لم يعتبر بنفسه فقط، بل اعتبر باللفظ، ونحو ذلك أن يقال ماء البئر هو ماء النهر إذا اعتبر جنس الماء، وتارة يقال: مثل ماء النهر إذا اعتبر قرار الماء، وعلى قول من جعل الإنسان ترك اللفظ حتى تنسى قال: معناه: إدا أزيل حكم آية أو أنسى لفظها نأت بما هو أوفق لكم وأقرب إلى أن يبلغوا به إلى ما أريد منكم، ثم قال: ﴿أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ﴾⟪2:106⟫ أي لا تحسبن أن تغييري الحكم حالا فحالا وإن لم آت بالثاني في الابتداء هو العجز، فإن من علم قدرته على كل شي لا يظن ذلك، وإنما يعتبر ذلك لا يرجع إلى مصلحة العباد، وبدأ الأليق بهم في الوقت المتقدم الحكم المتقدم وفى الوقت المتأخر الحكم المتأخر، وقال بعض المحققة أن الآية مع هذا الظاهر تنبئ عن معنى لطيف، وهو أن الله تعالى خلق الإنسان خلقة تدرجه من حال إلى حال إلى أنما يصير كاملا موصوفا بعام\n⟦1:287⟧\nصفاته ومتخصصا بالبقاء الأبدي والغنى السرمدي ومنفكا من الحاجات والنقصانات كلها، فنبه الله تعالى أن هذه الأحوال آيات له ينسخها إلى مثل ما هو كالأول من وجه وخير منه من وجه، ثم بين أنه تعالى قادر على ذلك إذ هو قادر على كل شيء، وقد تعلق الشافعي وأصحابه في قولهم: إن القرآن لا ينسخ إلا بالقرآن بهذه الآية، ووجه ذلك أن قولنا هدا خير من كذا، وأفضل منه يرجع إلى شرفه من ثلاثة أوجه إما إلى فضل موجده ، أو إلى جنسه، أو إلى تأثيره، مثال الأول: قولك: أفعال الله أفضل من أفعالنا، ومثال الثاني الملائكة أفضل من الحيوان ومثال الثالث: السيف أفضل من العصا ومثل يقال على ثلاثة معاني لها ثلاثة ألفاظ مماثلة في الجنس، ويقال لها الند مماثلة في الكيفية، ويقال لها الشبه ومماثلة في الكمية، ويقال لها المساواة، وثلاثتها يقال لها مثل، وقد ضمن الله تعالى أنه لا ينسخ آية إلا بخير منها أو مثلها، فالسنة ليست بخير من الآية ولا مثلها في الجنس، إذ جنس القرآن تتعلق به المعجزة وإن أمكن أن يقال: هي مثلها في الوصفين الآخرين، وأما وجه قول مخالفيه، فهو أن الله تعالى وإن ذكر الآية، فإنما أراد حكمها، لأن النسخ لا يكون إلا في الأحكام، فإذا قوله: ﴿بِخَيۡرٖ مِّنۡهَآ أَوۡ مِثۡلِهَآۗ﴾⟪2:106⟫ ليس إلا في الأحكام، فكأنه قيل: \" ما ننسخ من حكم الآية إلا نأت بخير منه أو مثله، فعلى هذا مدار الكلام وتعلق أهل الظاهر بالآية، حيث ذكروا أن الناسخ لابد أنما يكون أخف من المنسوخ، وذهبوا في الخفة إلى ما يستخفه النفس بالطبع، وذلك بعيدا فإن الشريعة مبنية على مخالفة النفس وعلى مجانبة مقتضى الطبع، ولهذا قيل هذا إذا عن أمران، فاشتبه وجه الصواب فتخير أثقلهما على النفس، وعلى هذا قوله تعالى: ﴿وَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَهُوَ خَيۡرٞ لَّكُمۡۖ﴾⟪2:216⟫.\nإن قيل: إذا لم يحمل خبر علي التخفيف فليست الثانية خيرا من الأولي في شي من الأحوال، لأن الأولى في الوقت أصلح وأفضل، والثانية في الوقت أصلح وأفضل، فقد تساويا في عظم المصلحة، وبطل أن يكون الثانية خبرا بأن يكون أثقل وأكثر أعمالا ليكون أجزل في الأجر وأكثر ثوابا، ومع هذا\n⟦1:288⟧\nفإن الثانية خير من الأولى في الوقت الثاني، لأن الأولى قد بطل العلم بها، وقوله بخير منها يعني في الوقت وتعلقهم بقوله تعالى: ﴿يُرِيدُ ٱللَّهُ أَن يُخَفِّفَ عَنكُمۡۚ﴾⟪4:28⟫، وقوله: ﴿يُرِيدُ ٱللَّهُ بِكُمُ ٱلۡيُسۡرَ﴾⟪2:185⟫ فبعيد، فإن التخفيف واليسر في الأمور الإلهية في الدنيا والآخرة هما مما تستثقله النفس، أما في الآخرة ، فأنه لا وصول إلى ذلك إلا بتحمل المشاق في الدنيا والعمل بالطاعات ومخالفة الهوى، وأما في الدنيا فإن التخفيف واليسر مع حصول العلم والصبر والعفة الواضحة عن الإنسان ثقل الجهل والجزع والخوف والفقر."}, {"a": [107], "v": 1, "p": 288, "ev": 1, "ep": 289, "sid": 289, "t": "قوله - عز وجل -\n﴿أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٍ﴾⟪2:107⟫\nالآية (107) - سورة البقرة.\nالولي يقال تارة لمن له موالاة نسبية أو خلف، وتارة لمن له ولاية سلطانية، وإنما ذكر الولي والنصير، وهما متقاربان بالعنف، لأنه قد ينفك الولي من النصرة بأن يكون ضعيفا، والنصير من الولاية بأن يكون عن المنصور أجنبيا، وقوله: ﴿وَمَا لَكُم مِّن دُونِ ٱللَّهِ﴾⟪2:107⟫ إذا تصور خطابا للكفار اقتضى وعيدا أي لأولي وناصر يحميكم عنه نحو قوله تعالي.\n﴿إِنَّكُم مِّنَّا لَا تُنصَرُونَ﴾⟪23:65⟫ إدا تصور خطابة للمؤمنين اقتضى تسكينا لهم أي لا تعتدوا بمن يواليكم وينصركم سواه، كقوله: ﴿ضَلَّ مَن تَدۡعُونَ إِلَّآ إِيَّاهُۖ﴾⟪17:67⟫، وإذا اعتبر بهما فالمعنيان فيهما موجودان أي لا تعتقدوا أن لكم وليا وناصرا إذا لم يكن الله وليكم تنبيها أنه تعالي هو الذي لا يمكن تصور ولي وناصر مع تصور\n⟦1:289⟧\nارتفاعه عز وجل، وإنما خص النبي - صلى الله عليه وسلم - بقوله: ﴿أَلَمۡ تَعۡلَمۡ﴾⟪2:107⟫ وإن كان الخطاب له ولغيره، لذكره العلم ولا أحد من البشر أعلم بذلك منه- عليه السلام-، أو قد وقف من أسرار ملكوت السموات والأرض على ما لم يوقف عليه غيره والقصد بالآية، أنهم لما أنكروا النسخ معرفتهم أنه تعالى ينقل عباده من حكم إلى حكم على ما يرى من مصالحهم، وبين أن ذلك ليس لعجزه، إذ هو قادر على كل شيء ومالك له، إنما قيل: لم كرر: \" ألم تعلم \"، ولم يعطف الثاني على الأول، قيل إنه لا جعل حكم الثاني كالعلة للأول أخرجه مخرج الأول، فكأنه قيل: \" هو على كل شي قدير \"، لأن له ملك السماوات والأرض، وإخراج\nالكلام على لفظ التقرير لكونه أبلغ في حكم الخطابة، وموضع قوله: (ومالكم) معطوف على موضع ﴿أَنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ﴾⟪2:107⟫ ..."}, {"a": [108], "v": 1, "p": 289, "ev": 1, "ep": 291, "sid": 290, "t": "قوله - عز وجل -\n﴿أَمۡ تُرِيدُونَ أَن تَسۡـَٔلُواْ رَسُولَكُمۡ كَمَا سُئِلَ مُوسَىٰ مِن قَبۡلُۗ وَمَن يَتَبَدَّلِ ٱلۡكُفۡرَ بِٱلۡإِيمَٰنِ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ﴾⟪2:108⟫\nالآية (108) - سورة البقرة.\nالسبيل والطريق يتقاربان لكن السبيل يقال على اعتبار السبل، كقولهم: طريق مسنون، ومنه أسبلت الإزار، والستر والسبلة المسترسل من الشعر على الشفة العليا والسبيل المطر مادام بين السماء والأرض، والطريق يقال على اعتبار طرقه بالأرجل، االسواء أصله يستعمل في المكان الذي يستوي فيه إليه مسافة الطرفين وفي ذلك معنى القصد والعدل، فصح أن يفسر بالوسط وبالقصد وبالعدل وليست هذه الألفاظ في تفسيره أقوالا مختلفة كما ظنه بعض المفسرين، وأما \" أم \"، فقيل هو معطوف على قوله: ﴿أَلَمۡ تَعۡلَمۡ﴾⟪2:107⟫، وتقديره: ألم تعلموا ذلك أم لم تعلموا فتسئلوا رسولكم، وقيل هو لاستئناف الاستفهام المفسر بها، كقول الشاعر:\nكذبتك عينك أم رأيت بواسط؟\n⟦1:290⟧\nوسبب نزول هذه الآية فيما روي أن أهل الكتاب سألوه أن ينزل عليهم كتابا من السماء، وذلك هما ذكره في قوله- عز وجل ﴿يَسۡـَٔلُكَ أَهۡلُ ٱلۡكِتَٰبِ﴾⟪4:153⟫ الآية-، وقيل: هو ما سأله مشركو العرب وهو قولهم له ﴿وَلَن نُّؤۡمِنَ لِرُقِيِّكَ حَتَّىٰ تُنَزِّلَ عَلَيۡنَا كِتَٰبٗا نَّقۡرَؤُهُۥۗ﴾⟪17:93⟫ وقيل: سألوه أن يجعل الصفا ذهبا، فقال: هو لكم كالمائدة لبني إسرائيل، فأبوا، وقيل، سألوه أن يجعل لهم ذات أنواط وهي شجرة تعلق فيها الأسلحة ليقتدوا بالمشركين في اتخاذها فقال عليه السلام: (الله أكبر، سألتم كما سال بنو إسرائيل موسى، فقالوا: اجعل لنا إلها كما لهم آلهة)،\nإن قيل: ما فائدة قوله: ﴿وَمَن يَتَبَدَّلِ ٱلۡكُفۡرَ بِٱلۡإِيمَٰنِ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ﴾⟪2:108⟫ ومعلوم أنه بدون الكفر بالإيمان يعلم أنه قد ضل؟ قيل سواء السبيل وفي ذلك تنبيه أن ضلالة سواء السبيل قائدة إلى الكفر بعد الإيمان، ومعناه: \" لا تسألوا رسولكم كما سئل موسى فتفضلوا سواء السبيل فيؤدي بكم إلى تبديل الكفر بالإيمان \"، فمبدأ ذلك الضلال عن\nسواء السبيل، ووجه آخر وهو أنه سمي معاندة الأنبياء عليهم السلام بعد حصول ما تسكن النفس إليه كفرا، إذ هي مؤدية إليه، كتسمية العصير خمرا، فقال: \" ومن يتبدل \" أي يطلب تبديل الكفر والإيمان أي بما حصل له من الدلالة المتقضية لسكون النفس فقد ضل سواء السبيل، ووجه ثالث، وهو أن ذلك نهاية التبكيت لن ظهر له الحق فعدل عنه إلى الباطل، وأنه كمن كان على وضح الطريق فتاه فيه، ووجه رابع: وهو أن سواء السبيل إشارة إلى الفطرة التي فطر الناس ما عليها، والإيمان إشارة إلى المكتسب من جهة الشرائع، فقال: ﴿وَمَن يَتَبَدَّلِ ٱلۡكُفۡرَ بِٱلۡإِيمَٰنِ﴾⟪2:108⟫ أي بالإيمان الكتاب فقد أبطله وضيع الفطرة التي فطر الناس عليها، فلا يرجى له نزوع عما هو عليه بعد ذلك ...\n⟦1:291⟧"}, {"a": [109], "v": 1, "p": 291, "ev": 1, "ep": 292, "sid": 292, "t": "قوله - عز وجل -:\n﴿وَدَّ كَثِيرٞ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ لَوۡ يَرُدُّونَكُم مِّنۢ بَعۡدِ إِيمَٰنِكُمۡ كُفَّارًا حَسَدٗا مِّنۡ عِندِ أَنفُسِهِم مِّنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمُ ٱلۡحَقُّۖ فَٱعۡفُواْ وَٱصۡفَحُواْ حَتَّىٰ يَأۡتِيَ ٱللَّهُ بِأَمۡرِهِۦٓۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ﴾⟪2:109⟫\nالآية (109) - سورة البقرة.\nالحسد: كراهية نعمة على مستحق لها، وعدت من عظائم الذنوب، إذ هو معاندة الله في إرادته، وهو شر من البخل، فإن الحسد بخل على الغير بنعمة من لا تنفد العطايا نعمه، والعفو ترك العقوبة على المذنب، والصفح ترك ترئته، وقد يعفو الإنسان ولا يصفح، وصفحت عنه: أي أوليته مني صفحة جميلة معرضا عن ذنبه، أو لقيت صفحته متجافيا عنه، أو تجاوزت الصفحة التي أثبت فيها ذنبه إلى غيرها من قولك: تصفحت الكتاب، وفي الآية تنبيه أن كثيرا من أهل الكتاب يتمنون ارتدادكم بعد إيمانكم حسدا، وقوله: ﴿مِّنۡ عِندِ أَنفُسِهِم﴾⟪2:109⟫ أي من عند هواهم كقوله تعالى: ﴿وَٱتَّبَعُوٓاْ أَهۡوَآءَهُم﴾، وعبر عن الهوى بالنفس وهي الأمارة بالسوء، وبين أنهم فعلوا ذلك بعد وضوح الحق لهم، ولكنهم بحسدهم وهوائهم لا يتحرونه، ولا يحبون أن يتحراه غيرهم، ثم أمر بالتجافى عنهم إلى أن يأتي الله بأمره تسكينا لهم ووعدا بتغييره لقدرته على كل شك، وروي عن ابن عباس- رضي الله تعالى عنهما- أن هذه الآية منسوخة بقوله: ﴿فَٱقۡتُلُواْ ٱلۡمُشۡرِكِينَ حَيۡثُ وَجَدتُّمُوهُمۡ﴾⟪9:5⟫، وقال غيره: هي غير منسوخه، وهذا الخلاف يرجع إلى اختلاف نظيرين، وذاك أن كل أمر ورد مقيدا بانتهاء ما معين أو غير معين فورود الأمر بخلافه يصح أن يقال: هو نسخ له من حيث إنه يرفع الأول، ويصح أن يقال: إنه ليس بنسخ، فإن النسخ في الأمر المطلق.\n⟦1:292⟧"}, {"a": [110], "v": 1, "p": 292, "ev": 1, "ep": 293, "sid": 293, "t": "قوله - عز وجل -:\n﴿وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَۚ وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنۡ خَيۡرٖ تَجِدُوهُ عِندَ ٱللَّهِۗ إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٞ﴾⟪2:110⟫\nالآية (110) - سورة البقرة.\nهذا معطوف على قوله: ﴿فَٱعۡفُواْ وَٱصۡفَحُواْ﴾⟪2:109⟫، ومعناه: اشتغلوا بالعبادات التي يعود عليكم فعلها نحو: ﴿وَٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ﴾⟪2:45⟫، وجعل ثواب الفعل نفس الفعل لكونه إياه في التقدير، وبهذا النظر سمي ثوابه وهو الثائب إليه، فلذلك قال: تجدوه، وبين أن كل خيري حصله الإنسان فمدخر له بخلاف عمل الكفار الذي قال فيه: ﴿وَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلٖ فَجَعَلۡنَٰهُ هَبَآءٗ مَّنثُورًا﴾⟪25:23⟫، وبخلاف عمل الدنيا الذي قال فيه: ﴿كَسَرَابِۭ بِقِيعَةٖ﴾⟪24:39⟫، وعلى ذلك قال: ﴿يَوۡمَ تَجِدُ كُلُّ نَفۡسٖ مَّا عَمِلَتۡ مِنۡ خَيۡرٖ مُّحۡضَرٗا وَمَا عَمِلَتۡ مِن سُوٓءٖ﴾⟪3:30⟫، وقال: ﴿فَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَيۡرٗا يَرَهُۥ ۝ وَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٖ شَرّٗا يَرَهُۥ﴾⟪99:7-8⟫، وأمنهم من ضياع ما يقدمونه بقوله: ﴿إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٞ﴾⟪2:110⟫ تنبيها على نحو قوله: ﴿لِيَجۡزِيَ ٱلَّذِينَ أَسَٰٓـُٔواْ بِمَا عَمِلُواْ وَيَجۡزِيَ ٱلَّذِينَ أَحۡسَنُواْ بِٱلۡحُسۡنَى﴾⟪53:31⟫.\nإن قيل: كيف قال تجدوه، ومن أحبط عمله لا يجده! قيل الخبر المقدم في الحقيقة هو الذي لم يحبط، فأما ما أحبط فقد أخرج من كونه خيرا [وإن كان] قد يسمى في بعض الأحوال خبرا بنظر من يضعف نظره ...\n⟦1:293⟧"}, {"a": [111], "v": 1, "p": 293, "ev": 1, "ep": 293, "sid": 294, "t": "قوله - عز وجل -:\n﴿وَقَالُواْ لَن يَدۡخُلَ ٱلۡجَنَّةَ إِلَّا مَن كَانَ هُودًا أَوۡ نَصَٰرَىٰۗ تِلۡكَ أَمَانِيُّهُمۡۗ قُلۡ هَاتُواْ بُرۡهَٰنَكُمۡ إِن كُنتُمۡ صَٰدِقِينَ﴾⟪2:111⟫\nالآية (111) - سورة البقرة.\nالبرهان: كل حجة لا يعتريها شبهة بوجه.\nوهود، قال الفراء: أصله يهود، فحذف ياؤه لكونها زائدة، وقال غيره: هو جمع هايد أي تائب نحو: ﴿إِنَّا هُدۡنَآ إِلَيۡكَۚ﴾⟪7:156⟫، وكأنه كان في الأصل اسم مدح لمن تاب منه، ثم صار بعد نسخ شريعتهم لازما لجماعتهم كالعلم لهم وجعل مقالهم ذلك، أماني من حيث أن الأمنية مقال منيعة عن تقدير، فيستعمل تارة في التقدير حقا كان أو باطلا على ذلك، حتى بين ما تمنى لك الماني، وتارة في المقال، وقوله: ﴿لَن يَدۡخُلَ﴾⟪2:111⟫ كلام \" ملفوف \" وتقديره: قالت اليهود لن يدخل الجنة إلا من كان هودا، وقالت النصارى: لن يدخلها إلا النصارى فأجمل اكتفاء بعلم السامع أن يرد كلأ إلي ما يقتضيه ونحوه في الإجمال قوله- عز وجل- ﴿جَعَلَ لَكُمُ ٱلَّيۡلَ وَٱلنَّهَارَ لِتَسۡكُنُواْ فِيهِ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ﴾⟪28:73⟫.\nثم [كذبهم] بعجزهم عن إقامة البرهان على ما ادعوه."}, {"a": [112], "v": 1, "p": 293, "ev": 1, "ep": 296, "sid": 294, "t": "قوله- عز وجل- ﴿بَلَىٰۚ مَنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنٞ فَلَهُۥٓ أَجۡرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ﴾⟪2:112⟫\nبل: رد لدعواهم وإثبات لضد حكمهم، والإسلام: الدخول في السلم، وقيل للانقياد إسلام، نحو:\nكما أسلم السلك من نظمه ...\nلألئ منحدرات صغارا\nلأن الانقياد للمسالم من مقتضى السلم، وجعل الإسلام في الشرع ضربين، ضربا قبل الإيمان دونه، وهو الاعتراف باللسان الذي يحقن الدماء حصل معه الاعتقاد الصحيح أو لم يحصل، وإياه\n⟦1:294⟧\nعنى بقوله - عز وجل -:\n﴿قَالَتِ ٱلۡأَعۡرَابُ ءَامَنَّاۖ قُل لَّمۡ تُؤۡمِنُواْ وَلَٰكِن قُولُوٓاْ أَسۡلَمۡنَا﴾⟪49:14⟫ وضربا بعد الإيمان وفوقه، وهو أن يكون مع الاعتراف اعتقاد بالقلب ووفاء بالفعل، وإياه عنى يوسف بقوله: ﴿تَوَفَّنِي مُسۡلِمٗا وَأَلۡحِقۡنِي بِٱلصَّٰلِحِينَ﴾⟪12:101⟫، وقال: ﴿إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلۡإِسۡلَٰمُۗ﴾⟪3:19⟫ أي الطاعة هي تسليم لأمر الله- عز وجل، وهذا الإسلام بين مبدأه ومنتهاه بون بعيد، وكان منتهاه على حسب طاقة البشر حال إبراهيم- عليه السلام- حيث ابتلى، فقيل له أسلم، فقال أسلمت لرب العالمين، ثم وفي بما كان منه، وهذا هو الإخلاص المراد من الأولياء، وأصل الوجه العضو المقابل من الإنسان فاستعير للمقابل من كل شيء حتى قيل: واجهته ووجهته، وقيل للقصد وجه، وللمقصد وجهة، وعلى ذلك ﴿أَسۡلَمَ وَجۡهَهُۥ﴾⟪2:112⟫، ﴿وَمَن يُسۡلِمۡ وَجۡهَهُۥٓ إِلَى ٱللَّهِ﴾⟪31:22⟫، ﴿أَسۡلَمۡتُ وَجۡهِيَ لِلَّهِ﴾⟪3:20⟫ وعلى ذلك قوله: ﴿وَجَّهۡتُ وَجۡهِيَ لِلَّذِي فَطَرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ حَنِيفٗاۖ﴾⟪6:79⟫.\nولما جعل دلك للقصد أضيف تارة إلى القاصد كما تقدم، وتارة إلى المقصور، كقولك: \" أردت بكذا وجه الله \"، وقد حمل على ذلك ﴿وَيَبۡقَىٰ وَجۡهُ رَبِّكَ﴾⟪55:27⟫، ﴿كُلُّ شَيۡءٍ هَالِكٌ إِلَّا وَجۡهَهُۥۚ﴾⟪28:88⟫، وقيل: الوجه في هذه المواضع اسم العضو مستعارا للذات، فقوله: أسلم وجهه أي نفسه والإحسان قيل هو الإتيان بلد فرض العبادة بالنفل، وبعد إقامة العدل بالفضل ولما كذبهم الله عز وجل فيما ادعوه\n⟦1:295⟧\nمن دخول الجنة بيد أن من أسلم نفسه له على حد ما قال الله تعالى: ﴿إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم﴾⟪9:111⟫، وكان قصده إياه فيما يتحراه وهو ملتزم مع فرائضه نوافل حصل له ما ادعوه وزيادة فإن له أجره وهو الجنة، ومع ذلك فلا خوف عليه في الدنيا ولا في الآخرة، أما في الدنيا فبأن يجعل له يقينا وصبرا قناعا تكفيه الخوف على شيء يفوته والجزع لشيء قد فاته، وأما في الآخرة فبأن يكفيه شدائده \" يوم لا يغني مولى عن مولى شيئأ \"\nإن قيل: كيف قال ﴿لَا خَوۡفٌ عَلَيۡهِمۡ﴾ وقد مدح المؤمنين على خوفهم بقوله: ﴿وَيَرۡجُونَ رَحۡمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓۚ﴾⟪17:57⟫ قيل: إن الذي نفي عنهم هو ما تقدم آنفا، والذي مدحهم به هو توفية حق العبادة، فإن مخافة الله إقامة عباداته وارتسام مرسوماته، ولذلك قيل: من لم تخف نفسه الدنيا فلا يعذبه [خائفا] وقيل: معنى ﴿أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنٞ﴾⟪2:112⟫ أي: من آمن وعمل صالحا، وما تقدم منطو على هذا ...\n⟦1:296⟧"}, {"a": [113], "v": 1, "p": 296, "ev": 1, "ep": 297, "sid": 297, "t": "قوله - عز وجل -:\n﴿وَقَالَتِ ٱلۡيَهُودُ لَيۡسَتِ ٱلنَّصَٰرَىٰ عَلَىٰ شَيۡءٖ وَقَالَتِ ٱلنَّصَٰرَىٰ لَيۡسَتِ ٱلۡيَهُودُ عَلَىٰ شَيۡءٖ وَهُمۡ يَتۡلُونَ ٱلۡكِتَٰبَۗ كَذَٰلِكَ قَالَ ٱلَّذِينَ لَا يَعۡلَمُونَ مِثۡلَ قَوۡلِهِمۡۚ فَٱللَّهُ يَحۡكُمُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ﴾⟪2:113⟫\nالآية (113) - سورة البقرة.\nالكتاب يتناول كل كتاب منزل، والفرقان يقال في التوراة وفي القرآن، والقرآن يختص بالمنزل على محمد - صلى الله عليه وسلم -، وروي أنه لما قدم نصارى نجران علي رسول - صلى الله عليه وسلم - أتتهم أحبار يهود فتنازعوا عنده، وقال كلا الفريقين للآخر: لستم عدي شيء، فأنزل الله-عز وجل - هذه الآية،\nإن قيل: كيف عرض تعالى بتكذيبهم فيما ادعوه وقد صدق الفريقان على قول المسلمين؟ قيل: ليس قول أحد الفريقين بسديد من وجه، إذ قد بتوا الحكم وليس ذلك على البت والقطع، فلكا الفريقين في وقت وعلى وجه على حق، على أن القصد بالآية الدلالة على جهلهم وتخبطهم مع تشاركهم في قراءة التوراة دالة على ما اختلفوا فيه، فبين أن كلا الفريقين حائد عن الطريق، وأنهم في الجهل أو التجاهل\nكالمشركين الذين لا كتاب لهم في دعواهم على أهل الكتابي والمسلمين أنهم ليسوا على شي، ثم توعد الفريقين بحكمه بينهم [يوم القيامة] وقد أبهم حكمه فيدخل فيه كل قول قالوه من قول من قال: عني إنصاف المظلوم من الظالم، وقول من قال: عني تعريف المكذب من المكذب، وقول من قال: مثل قوله ﴿وَإِنَّ جَهَنَّمَ لَمُحِيطَةُۢ بِٱلۡكَٰفِرِينَ﴾.\n⟦1:297⟧"}, {"a": [114], "v": 1, "p": 297, "ev": 1, "ep": 298, "sid": 298, "t": "قوله - عز وجل -:\n﴿وَمَنۡ أَظۡلَمُ مِمَّن مَّنَعَ مَسَٰجِدَ ٱللَّهِ أَن يُذۡكَرَ فِيهَا ٱسۡمُهُۥ وَسَعَىٰ فِي خَرَابِهَآۚ أُوْلَٰٓئِكَ مَا كَانَ لَهُمۡ أَن يَدۡخُلُوهَآ إِلَّا خَآئِفِينَۚ لَهُمۡ فِي ٱلدُّنۡيَا خِزۡيٞ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٞ﴾⟪2:114⟫\nالآية (114) - سورة البقرة.\nالمنع، أن يحال بين من المراد ومريده، ولما كان الشيء قد يمنع ضنا به صار المنع متعارفا في المتنافس فيه، والسعي مشئ بسرعة، وهو دون العدو، وخص بأنواع من السعي منها: السعاية، أي الوشاية وسعي العبد في اكتساب ما يعتق به والتصرف، للتكسب، ولجباية الصدقة حتى صار الساعي معروفة في جابي الصدقة، وجعل المساعدة كناية عن الفجور بالأمة والخراب ضد\nالعمارة، وجعل الخربة لسعة خرق الأذن تشبيها بالخراب، وشبه عروة المزادة بها، فقيل خربة، والخارب: السارق لتخريبه، أو لكونه سكانا في خراب متوحشا عن الناس، فيكون بنائه كباد وحاضر، وقيل: هو مخصوص بسارق الإبل خاصة، والأولى بالمساجد أن تكون عامة في كل مكان مرشح للصلاة، فقد قال عليه السلام.\n\" جعلت لي الأرض مسجدا وطهوا \"، وعظم تعالى ظلم من سعي في المنع من ذكر الله وتخريب الأمكنة المختصة بأهل الشرائع المحقة مسجدا كان أو غير مسجد، وليس\nالتخريب الهدم فقط، بل تعطيله عن عباده الله- عز وجل-.\nوقول ابن عباس ومجاهد: إنه عني به الروم إذ خربوا بيت المقدس، وقول غيره إنه عني \" بخت نصر \" لما خربه، وقول من قال: إنما عني به المشركين إذ صدوا النبي عليه السلام عن المسجد الحرام،\n⟦1:298⟧\nوكل ذلك أمثلة منهم لحكمه وسبب النزول هذه الآية لا أنه لم يرد بها غير ذلك، يبين دلك أنه قال: مساجد بلفظ الجمع، وقوله: ﴿مَا كَانَ لَهُمۡ أَن يَدۡخُلُوهَآ إِلَّا خَآئِفِينَۚ﴾⟪2:114⟫ لفظه خبر، ومعناه منطو عليه وعلى الأمر، فإن بيوت الله- عز وجل ممنوعة عن الكفار في دار الإسلام إلا بإذن، ويكونون خائفين، والحكم أن لا يمكنوا إلا بشرط حاجة تقتضي ذلك، ثم ثبت لهم الخزي في الدنيا، وذلك تارة بالهوان الذي يجري عليهم، وتارة بأخذ الجزية منهم، وقتلهم، والسبي، منهم، ومنعهم عن كثير مما يباح للمسلم، وإليه نظر قتادة وجماعة وفسروا به، وتارة بالهوان الذي يلحقهم في أنفسهم من جنبهم وجزعهم وخوفهم وسائر الآفات النفسية وتارة من حيائهم من عقلهم لاضطراب نفوسهم وقلوبهم وقلة سكونهم لما اختاروه، وإلى ذلك أشار تعالى بقوله: ﴿وَمَن يُشۡرِكۡ بِٱللَّهِ فَكَأَنَّمَا خَرَّ مِنَ ٱلسَّمَآءِ فَتَخۡطَفُهُ ٱلطَّيۡرُ﴾⟪22:31⟫."}, {"a": [115], "v": 1, "p": 298, "ev": 1, "ep": 300, "sid": 299, "t": "قوله - عز وجل -:\n﴿وَلِلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ فَأَيۡنَمَا تُوَلُّواْ فَثَمَّ وَجۡهُ ٱللَّهِۚ إِنَّ ٱللَّهَ وَٰسِعٌ عَلِيمٞ﴾⟪2:115⟫\nالآية (115) - سورة البقرة.\nالمشرق والمغرب تارة يقالان بلفظ الواحد إما إشارة إلى ناحية الأرض، وإما إلى المطلع والمغيب، وتارة بلفظ التثنية إشارة إلى مشرقي ومغربي الشتاء والصيف، وتارة بلفظ الجمع اعتبارا باختلاف المغارب والمطالع كل يوم، وشرقت الشمس طلعت، وأشرقت: أضاءت وذلك إذا كثير شروقها، وشرقت اللحم: ألقيته على الشمس المشرق، والشرف الصلب لأنه يقام فيه صلاة [العيد] عند شروقها، وشرق الثوب بالصبغ تشبيها بلون الشرقة، والغروب للشمس تصور منه بعد ذهابها عن العمارة، فيقال لدى تباعد غروب، ومنه الغروب لكونه مبعدا في الذهاب، وغارب السنام لبعده عن المنال، وغرب السيف أبعد جزء من صحيفته، ثم تصور منه حدته، فقيل لسان غرب وسمي الدلو غربا\n⟦1:299⟧\nلتصور بعدها في البئر، ثم سمي الماء به كتسميتهم إياها بالذنوب لكونه فيها، والغرب للذهب لكونه غريبا فيما بين الجواهر، والغرب لبعده عن المثمرات من الأشجار، والآية توكيد لا تقدم أنه عني بالمساجد حيث ما صلى فكأنه قيل: لاعتبروا الأمكنة، فلله- عز وجل- ملك الدنيا، وحيث ما توجهتم فهو موجود يمكنكم الوصول إليه، إذ ليس هو جوهرا ولا عرضا، فيكون بكونه في جانب مفرغا جانبا ونبه بقوله: \" بواسع \" على إحاطته بالأشياء، \" وبالعليم \" أنه لا يخفى عليه خافية، وقد حمل أكثر المفسرين الآية على أنها واردة في القبلة، فمنهم من قال ذلك توطئة لجواز نقلها وتقرير في نفوسهم أن ليس المعبود [سبحانه] في حيز دون حيز، وقيل إن دلك في زمان كان يجوز الصلاة فيه إلى كل جهة حتى أمروا بقوله: ﴿فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ﴾ وهو قول قيادة وابن زيد، وذلك بعيدة لأن القبلة كانت مخصوصة وعلى ذلك قوله ﴿وَمَا جَعَلۡنَا ٱلۡقِبۡلَةَ ٱلَّتِي كُنتَ عَلَيۡهَآ﴾⟪2:143⟫ وقيل إن دلك في النافلة وجوازها حيث ما توجهت بنا الراحلة، وإليه ذهب ابن عمر، وقيل إن قوما صلوا في ظلمة خفيت عليهم جهة القبلة، فلما أصبحوا كانوا قد صلوا إلى غير القبلة، فأنزل الله - عز وجل- ذلك وإليه ذهب ابن عباس وجماعة، وقد تقدم معنى وجه الله.\n⟦1:300⟧"}, {"a": [116], "v": 1, "p": 300, "ev": 1, "ep": 302, "sid": 301, "t": "قوله - عز وجل -:\n﴿وَقَالُواْ ٱتَّخَذَ ٱللَّهُ وَلَدٗاۗ سُبۡحَٰنَهُۥۖ بَل لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ كُلّٞ لَّهُۥ قَٰنِتُونَ﴾⟪2:116⟫\nالآية (116) - سورة البقرة.\nالقنوت: لزوم الطاعة مع الخضوع، ولما كان لهما فسر بكل واحد منهما، فقيل في قوله: ﴿وَقُومُواْ لِلَّهِ قَٰنِتِينَ﴾⟪2:238⟫ أي خاضعين، وقيل طائعين، ولما كان من تمام القنوت القيام والسكون ما لم يكن أمر بخلافه واستعمل فيهما، فقيل في قول النبي - صلى الله عليه وسلم - لما قيل له: أي الصلاة أفضل؟ قال: طول القنوت \" أي القيام، ولما ادعى النصارى في المسيح واليهود في عزير أنهما أبناء الله، ومشركوا العرب في الملائكة أنهم بنات الله تقدس ألفه تعالى عن ذلك، نبه على أقوى حجة على نفي ذلك وبيانها هو أن\nلكل موجود في العالم مخلوقا طبيعيا أو معمولا صناعيا عرضا وكمالا أوجد لأجله، وإن كان قد يصلح لغيره على سبيل العرض كاليد للبطش، والرجل للمشي، والسكين لقطع مخصوص، والمنشار للنشر وإن كان اليد قد يصلح للمشي في حال، والرجل للتناول، لكن ليس على التمام، والغرض في الولد للإنسان إنما هو لأن يبقى به نوعه، وجزء منه لا لم يجعل الله له سبيلا إلى بقائه بشخصه، فجعل له بذرا لحفظ نوعه، ويقوي دلك أنه لم يجعل الشمس والقمر وسائر الأجرام السماوية بذرا، واستخلافا لما لم يجعل لها فناء النبات والحيوان، ولما كان الله تعالى هو الباقي الدائم بلا ابتداء ولا انتهاء، لم يكن لاتخاذه الولد لنفسه معنى، ولهذا قال سبحانه أن يكون له ولد، أي هو منزه عن السبب المقتضي للولد، ثم لما كان اقتناء الولد لفقر ما، ودلك لما تقدم أن الإنسان افتقر إلى نسل يخلفه لكونه غير كامل في نفسه، بين تعالى بقوله ﴿لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ﴾⟪2:116⟫ أنه لا يتوهم له فقر فيه فيحتاج إلى اتخاذ\n⟦1:301⟧\nماهو سد لفقره، فصار في قوله: ﴿لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ﴾⟪2:116⟫ دلالة ثانية، ثم زار حجة بقوله: (قانتون) وهو أنه لما كان الولد يعتقد فيه خدمة الأب ومظاهرته كما قال: ﴿وَجَعَلَ لَكُم مِّنۡ أَزۡوَٰجِكُم بَنِينَ وَحَفَدَةٗ﴾⟪16:72⟫، بين أن كل ما في السماوات والأرض مع كونه ملكا له فأنت له أيضا إما طائعا، وإما كارها، وإما مسحرا، كقوله: ﴿وَلِلَّهِۤ يَسۡجُدُۤ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ طَوۡعٗا وَكَرۡهٗا﴾⟪13:15⟫، وقوله: ﴿وَإِن مِّن شَيۡءٍ إِلَّا يُسَبِّحُ بِحَمۡدِهِۦ﴾⟪17:44⟫، وهذا أبلغ حجة لمن هو على المحجة ...\nإن قيل: من أين وقع لهم الشبهة في نسبة الولد إلي الله تعالى؟ قيل: قد ذكر أن في الشرائع المتقدمة كانوا يطلقون على البارئ تعالى اسم \" الأب \"، وعلى الكبير منهم اسم الإله- حتى إنهم قالوا: إن الأب هو الرب الأصغر، وإن الله هو الأب الأكبر \"، وكانوا يريدون بدلك أنه تعالى هو السبب الأول في وجود الإنسان، وأن الأب هو السبب الأخير في وجوده، وأن الأب هو معبود الابن من وجه، أي مخدومه، وكانوا يقولون للملائكة آلهة كما قالت العرب للشمس إلهة، وكانوا يقصدون معنى صحيحا\nكما يقصد علمائنا بقولهم:.\nالله محب ومحبوب، ومريد ومراد، ونحو ذلك من الألفاظ، وكما يقال للسلطان الملك وقول الناس \" رب الأرباب.\n، إله الألهة \"، \" ملك الملوك \"، ومما يكشف عن تقدم ذلك التعارف ويقوي ذلك ما يروى أن يعقوب كان يقال له \" مكر الله \"، وأن عيسى كان يقول، \" أنا ذاهب إلي أبي، ونحو دلك من الألفاظ، ثم تصور الجهلة منهم باخرة معنى الولادة الطبيعية، فصار ذلك منهيا عن التفوه به في شرعنا تنزها عن هذا الاعتقاد، حتى صار إطلاقه وإن قصد به ما قصده هؤلاء قرين\nالكفر، وقد استدل بعض الفقهاء بهذه الآية على أن الملك لا يقارن الولادة، وأن من ملك والده أو مولوده عتق عليه، لأنه تعالى نفي عن نفسه الولد بإثبات الملك له وهذا بعيد عما قصد في الآية بالمقال وإن كان فيه مجال للجدال ...\n⟦1:302⟧"}];
